        'h1{font-size:20px;margin:0 0 4px}.sub{color:var(--cx-text-mute, #78716c);font-size:13px;margin:0 0 18px}'
        'table{width:100%;border-collapse:collapse;background:var(--cx-card, #fff);border-radius:12px;overflow:hidden;'
