@bp.route('/api/programacion/regenerar-oc', methods=['POST'])
def prog_regenerar_oc():
    """Borra solicitudes auto-generadas Pendientes + sus OCs Borrador y
    vuelve a llamar al generador con los datos ACTUALES de Programación.

    Útil cuando el cálculo cambió (más producciones programadas, nuevos
    déficits) y las solicitudes viejas tienen cantidades obsoletas.

    NO toca solicitudes en estado Aprobada/Pagada (esas se respetan como
    histórico). Solo borra Pendientes auto-generadas (observaciones LIKE
    '%Centro Programación%' o '%Centro Programacion%' o '%Auto-generada%').
    """
    if not _auth():
        return jsonify({'error': 'No autenticado'}), 401

    conn = get_db()
    c = conn.cursor()
    deleted = {'solicitudes': 0, 'ordenes_compra': 0, 'items': 0}

    try:
        # 1. Listar solicitudes auto-generadas Pendientes y sus OCs
        rows = c.execute("""
            SELECT numero, numero_oc FROM solicitudes_compra
            WHERE estado = 'Pendiente'
              AND categoria IN ('Materia Prima', 'MP')
              AND (observaciones LIKE '%Centro Programación%'
                   OR observaciones LIKE '%Centro Programacion%'
                   OR observaciones LIKE '%Auto-generada%')
        """).fetchall()
        nums_sol = [r[0] for r in rows]
        nums_oc = [r[1] for r in rows if r[1]]

        if nums_sol:
            ph_sol = ','.join('?' * len(nums_sol))
            try:
                d = c.execute(f"DELETE FROM solicitudes_compra_items WHERE numero IN ({ph_sol})", nums_sol)
                deleted['items'] = d.rowcount or 0
            except sqlite3.OperationalError:
                pass
            d = c.execute(f"DELETE FROM solicitudes_compra WHERE numero IN ({ph_sol})", nums_sol)
            deleted['solicitudes'] = d.rowcount or 0

        if nums_oc:
            ph_oc = ','.join('?' * len(nums_oc))
            # Solo borrar OCs en estado Borrador (las Aprobadas/Pagadas son histórico)
            ocs_borrar = [r[0] for r in c.execute(
                f"SELECT numero_oc FROM ordenes_compra WHERE numero_oc IN ({ph_oc}) AND estado='Borrador'",
                nums_oc
            ).fetchall()]
            if ocs_borrar:
                ph_b = ','.join('?' * len(ocs_borrar))
                try:
                    c.execute(f"DELETE FROM ordenes_compra_items WHERE numero_oc IN ({ph_b})", ocs_borrar)
                except sqlite3.OperationalError:
                    pass
                d = c.execute(f"DELETE FROM ordenes_compra WHERE numero_oc IN ({ph_b})", ocs_borrar)
                deleted['ordenes_compra'] = d.rowcount or 0

        conn.commit()
    except Exception as e:
        conn.rollback()
        return jsonify({
            'error': 'Falló el borrado de solicitudes viejas',
            'detalle': str(e),
        }), 500

    # 2. Recalcular déficit con la lógica correcta (total_g - stock una sola
    # vez). Misma fuente de verdad que /programacion para no divergir.
    mp_deficit = _mp_deficit_para_oc(conn, days_ahead=90)

    if not mp_deficit:
        return jsonify({'ok': True, 'mensaje': 'Sin déficits actuales — solo se borraron viejas',
                        'borradas': deleted, 'creadas': []})

    SIN_PROV = 'Sin asignar'
    grupos = {}
    for cod, info in mp_deficit.items():
        prov = info.get('proveedor') or SIN_PROV
        grupos.setdefault(prov, []).append({
            'codigo': cod,
            'nombre': info['nombre'],
            'deficit_g': info['deficit_g'],
            'productos': info['productos'],
        })

    from datetime import datetime as _dt
    year = _dt.now().strftime('%Y')
    # FIX 25-jul (auditoría): iba `conn` y el helper espera un CURSOR (hace c.execute y
    # después c.fetchall(); una conexión no tiene fetchall) → AttributeError → 500 SIEMPRE.
    # Los otros 14 llamadores del repo pasan cursor; estos 2 quedaron mal desde el M45 y
    # nadie lo vio porque los tests probaban el MOTOR de déficit, nunca el endpoint que
    # ESCRIBE. En regenerar-oc es peor: el borrado de las viejas ya commiteó más arriba.
    last_n = siguiente_correlativo(conn.cursor(), 'solicitudes_compra', 'numero', f"SOL-{year}-") - 1  # PG-safe · M45 (loop hace +1)
    n_sol = last_n
    user = session.get('compras_user', 'Sistema')

    creadas = []
    proveedores_ordenados = sorted(grupos.keys(), key=lambda p: (p == SIN_PROV, p.lower()))

    try:
        for prov in proveedores_ordenados:
            items = grupos[prov]
            if not items:
                continue
            n_sol += 1
            sol_numero = f"SOL-{year}-{n_sol:04d}"
            num_oc = siguiente_numero_oc(conn.cursor(), year)  # PG-safe (drift CAST · 16-jun) · FIX 25-jul: cursor, no conexión

            mps_resumen_items = sorted(items, key=lambda x: -x['deficit_g'])[:5]
            mps_resumen = ', '.join([
                (it['nombre'][:25] + f" ({int(it['deficit_g']):,} g)".replace(',', '.'))
                for it in mps_resumen_items
            ])
            if len(items) > 5:
                mps_resumen += f' +{len(items) - 5} más'

            es_sin_prov = (prov == SIN_PROV)
            obs_prefix = (
                "REQUIERE ASIGNAR PROVEEDOR — " if es_sin_prov else
                "Auto-generada Centro Programación — "
            )
            obs = f"{obs_prefix}Proveedor: {prov} · {len(items)} MPs · {mps_resumen}"
            if es_sin_prov:
                obs += " · ACCIÓN: Catalina debe asignar proveedor en /admin → Catálogo MPs y disparar Generar OC nuevamente."

            conn.execute("""INSERT INTO solicitudes_compra
                (numero, fecha, estado, solicitante, urgencia, observaciones,
                 area, empresa, categoria, tipo, numero_oc)
                VALUES (?, datetime('now', '-5 hours'), 'Pendiente', ?, 'Alta', ?,
                        'Produccion', 'Espagiria', 'Materia Prima', 'Compra', ?)""",
                (sol_numero, user, obs, num_oc))

            conn.execute("""INSERT INTO ordenes_compra
                (numero_oc, fecha, estado, proveedor, valor_total, observaciones, creado_por, categoria)
                VALUES (?, datetime('now', '-5 hours'), 'Borrador', ?, 0, ?, ?, 'MP')""",
                (num_oc, prov,
                 f"OC sugerida desde Centro Programación · {len(items)} MPs",
                 user))

            items_created_this = []
            for it in items:
                just = f"Déficit para producción de: {', '.join(it['productos'][:3])}"
                if len(it['productos']) > 3:
                    just += f' +{len(it["productos"])-3} más'
                conn.execute("""INSERT INTO solicitudes_compra_items
                    (numero, codigo_mp, nombre_mp, cantidad_g, unidad, justificacion)
                    VALUES (?,?,?,?,?,?)""",
                    (sol_numero, it['codigo'], it['nombre'],
                     it['deficit_g'], 'g', just))
                try:
                    conn.execute("""INSERT INTO ordenes_compra_items
                        (numero_oc, codigo_mp, nombre_mp, cantidad_g, precio_unitario, subtotal)
                        VALUES (?,?,?,?,0,0)""",
                        (num_oc, it['codigo'], it['nombre'], it['deficit_g']))
                except sqlite3.OperationalError:
                    pass
                items_created_this.append({
                    'codigo': it['codigo'], 'nombre': it['nombre'],
                    'deficit_g': round(it['deficit_g'], 1),
                })

            creadas.append({
                'solicitud': sol_numero, 'orden_compra': num_oc,
                'proveedor': prov, 'n_items': len(items_created_this),
                'requiere_asignacion': es_sin_prov,
            })
        conn.commit()
    except Exception as e:
        conn.rollback()
        return jsonify({
            'error': 'Borrado OK pero falló la regeneración',
            'detalle': str(e),
            'borradas': deleted,
        }), 500

    n_total_mps = sum(len(g) for g in grupos.values())
    n_proveedores = len([p for p in grupos.keys() if p != SIN_PROV])
    n_huerfanos = len(grupos.get(SIN_PROV, []))

    return jsonify({
        'ok': True,
        'borradas': deleted,
        'creadas': creadas,
        'total_solicitudes_nuevas': len(creadas),
        'total_mps': n_total_mps,
        'proveedores_resueltos': n_proveedores,
        'mps_huerfanos': n_huerfanos,
        'mensaje': (
            f"✅ Borradas {deleted['solicitudes']} solicitudes viejas + "
            f"creadas {len(creadas)} nuevas con datos actuales "
            f"({n_total_mps} MPs, {n_proveedores} proveedores"
            + (f", {n_huerfanos} huérfanos" if n_huerfanos else "") + ")"
        ),
    })


@bp.route('/api/programacion/generar-oc', methods=['POST'])
def prog_generar_oc():
    """Genera solicitudes de compra agrupadas POR PROVEEDOR.

    Política operacional definida con el dueño del negocio:
      - 1 solicitud por cada proveedor que tenga MPs en déficit
      - 1 solicitud SEPARADA con todas las MPs sin proveedor asignado
        (proveedor='Sin asignar') para que Catalina las revise, asigne en
        /admin → Catálogo MPs, y al refrescar la próxima vez ya queden
        agrupadas en sus proveedores correctos.

    Lee el proveedor de cada MP desde maestro_mps.proveedor.
    """
    if not _auth():
        return jsonify({'error': 'No autenticado'}), 401

    conn = get_db()

    # Cálculo correcto: agrega total_g por MP y resta stock UNA vez.
    # Antes se sumaban deficits per-product (under-cuenta cuando hay stock
    # parcial). Esto deja las cantidades del OC alineadas con lo que muestra
    # /programacion (planificacion_estrategica + mps-deficit).
    mp_deficit = _mp_deficit_para_oc(conn, days_ahead=90)

    if not mp_deficit:
        return jsonify({
            'ok': True,
            'mensaje': 'No hay déficits de MP — sin OC necesaria',
            'creadas': []
        })

    # Agrupar MPs en déficit por proveedor; sin proveedor → '(Sin asignar)'
    SIN_PROV = 'Sin asignar'
    grupos = {}  # proveedor → lista de items
    for cod, info in mp_deficit.items():
        prov = info.get('proveedor') or SIN_PROV
        grupos.setdefault(prov, []).append({
            'codigo': cod,
            'nombre': info['nombre'],
            'deficit_g': info['deficit_g'],
            'productos': info['productos'],
        })

    # Numero de SOL inicial
    from datetime import datetime as _dt
    year = _dt.now().strftime('%Y')
    # FIX 25-jul (auditoría): iba `conn` y el helper espera un CURSOR (hace c.execute y
    # después c.fetchall(); una conexión no tiene fetchall) → AttributeError → 500 SIEMPRE.
    # Los otros 14 llamadores del repo pasan cursor; estos 2 quedaron mal desde el M45 y
    # nadie lo vio porque los tests probaban el MOTOR de déficit, nunca el endpoint que
    # ESCRIBE. En regenerar-oc es peor: el borrado de las viejas ya commiteó más arriba.
    last_n = siguiente_correlativo(conn.cursor(), 'solicitudes_compra', 'numero', f"SOL-{year}-") - 1  # PG-safe · M45 (loop hace +1)
    n_sol = last_n
    user = session.get('compras_user', 'Sistema')

    creadas = []
    huerfana_info = None

    # Ordenar: primero proveedores reales, al final 'Sin asignar' para que
    # quede visualmente claro como solicitud "por revisar"
    proveedores_ordenados = sorted(
        grupos.keys(),
        key=lambda p: (p == SIN_PROV, p.lower())
    )

    try:
        for prov in proveedores_ordenados:
            items = grupos[prov]
            if not items:
                continue
            n_sol += 1
            sol_numero = f"SOL-{year}-{n_sol:04d}"
            num_oc = siguiente_numero_oc(conn.cursor(), year)  # PG-safe (drift CAST · 16-jun) · FIX 25-jul: cursor, no conexión

            # Resumen de MPs principales para observaciones (legibilidad)
            mps_resumen_items = sorted(items, key=lambda x: -x['deficit_g'])[:5]
            mps_resumen = ', '.join([
                (it['nombre'][:25] + f" ({int(it['deficit_g']):,} g)".replace(',', '.'))
                for it in mps_resumen_items
            ])
            if len(items) > 5:
                mps_resumen += f' +{len(items) - 5} más'

            es_sin_prov = (prov == SIN_PROV)
            obs_prefix = (
                "REQUIERE ASIGNAR PROVEEDOR — " if es_sin_prov else
                "Auto-generada Centro Programación — "
            )
            obs = (
                f"{obs_prefix}Proveedor: {prov} · "
                f"{len(items)} MPs · {mps_resumen}"
            )
            if es_sin_prov:
                obs += " · ACCIÓN: Catalina debe asignar proveedor en /admin → Catálogo MPs y disparar Generar OC nuevamente."

            conn.execute("""INSERT INTO solicitudes_compra
                (numero, fecha, estado, solicitante, urgencia, observaciones,
                 area, empresa, categoria, tipo, numero_oc)
                VALUES (?, datetime('now', '-5 hours'), 'Pendiente', ?, 'Alta', ?,
                        'Produccion', 'Espagiria', 'Materia Prima', 'Compra', ?)""",
                (sol_numero, user, obs, num_oc))

            # OC asociada con el proveedor correcto (o 'Sin asignar')
            valor_estimado_total = 0
            conn.execute("""INSERT INTO ordenes_compra
                (numero_oc, fecha, estado, proveedor, valor_total, observaciones, creado_por, categoria)
                VALUES (?, datetime('now', '-5 hours'), 'Borrador', ?, 0, ?, ?, 'MP')""",
                (num_oc, prov,
                 f"OC sugerida desde Centro Programación · {len(items)} MPs",
                 user))

            items_created_this = []
            for it in items:
                just = f"Déficit para producción de: {', '.join(it['productos'][:3])}"
                if len(it['productos']) > 3:
                    just += f' +{len(it["productos"])-3} más'
                conn.execute("""INSERT INTO solicitudes_compra_items
                    (numero, codigo_mp, nombre_mp, cantidad_g, unidad, justificacion)
                    VALUES (?,?,?,?,?,?)""",
                    (sol_numero, it['codigo'], it['nombre'],
                     it['deficit_g'], 'g', just))
                try:
                    conn.execute("""INSERT INTO ordenes_compra_items
                        (numero_oc, codigo_mp, nombre_mp, cantidad_g, precio_unitario, subtotal)
                        VALUES (?,?,?,?,0,0)""",
                        (num_oc, it['codigo'], it['nombre'], it['deficit_g']))
                except sqlite3.OperationalError:
                    pass
                items_created_this.append({
                    'codigo': it['codigo'],
                    'nombre': it['nombre'],
                    'deficit_g': round(it['deficit_g'], 1),
                })

            entry = {
                'solicitud': sol_numero,
                'orden_compra': num_oc,
                'proveedor': prov,
                'n_items': len(items_created_this),
                'items': items_created_this,
                'requiere_asignacion': es_sin_prov,
            }
            creadas.append(entry)
            if es_sin_prov:
                huerfana_info = entry

        conn.commit()
    except Exception as e:
        conn.rollback()
        return jsonify({
            'error': 'Falló la generación de OCs',
            'detalle': str(e),
        }), 500

    n_total_mps = sum(len(g) for g in grupos.values())
    n_proveedores = len([p for p in grupos.keys() if p != SIN_PROV])
    n_huerfanos = len(grupos.get(SIN_PROV, []))

    msg = f'{len(creadas)} solicitudes creadas — {n_total_mps} MPs en {n_proveedores} proveedores'
    if n_huerfanos:
        msg += f' + 1 solicitud SIN ASIGNAR ({n_huerfanos} MPs huérfanos para revisar)'

    return jsonify({
        'ok': True,
        'creadas': creadas,
        'total_solicitudes': len(creadas),
        'total_mps': n_total_mps,
        'proveedores_resueltos': n_proveedores,
        'mps_huerfanos': n_huerfanos,
        'huerfana': huerfana_info,
        'mensaje': msg,
    })


@bp.route('/api/programacion/mps-deficit')
def prog_mps_deficit():
    """Lista plana de MPs con déficit real según Centro de Programación.

    A diferencia de /api/alertas-reabastecimiento (que compara stock_actual
    < stock_minimo y depende de un campo desactualizado), esta calcula
    déficit REAL: necesidad para producciones futuras + velocidad de ventas
    proyectada vs stock actual.

    Cada item: codigo_mp, nombre, stock_actual_g, deficit_g, productos_afectados,
                proveedor, lead_time_estimado.
    """
    if not _auth():
        return jsonify({'error': 'No autenticado'}), 401
    conn = get_db()
    try:
        china_mps_set = _get_china_mps(conn)
        # Misma fuente de verdad que /generar-oc y /planificacion
        mp_def_raw = _mp_deficit_para_oc(conn, days_ahead=90)
        if not mp_def_raw:
            return jsonify({'mps': [], 'total': 0, 'deficit_total_kg': 0})

        items = []
        for mid, info in mp_def_raw.items():
            items.append({
                'codigo_mp': mid,
                'nombre': info['nombre'],
                'stock_actual_g': info['stock_g'],
                'deficit_g': info['deficit_g'],
                'productos_afectados': info['productos'],
                'es_china': mid in china_mps_set,
                'proveedor': info.get('proveedor', ''),
            })
        items.sort(key=lambda x: -x['deficit_g'])
        deficit_total_kg = sum(i['deficit_g'] for i in items) / 1000.0

        return jsonify({
            'mps': items,
            'total': len(items),
            'deficit_total_kg': round(deficit_total_kg, 2),
            'china_count': sum(1 for i in items if i.get('es_china')),
        })
    except Exception as e:
        import traceback
        return jsonify({
            'error': str(e),
            'traceback': traceback.format_exc()[-500:],
            'mps': [],
            'total': 0,
        }), 500


@bp.route('/api/programacion/n-alertas')
def prog_n_alertas():
    """Endpoint rápido — retorna solo el conteo de alertas (para badge en Compras)."""
    if not _auth():
        return jsonify({'n': 0})
    conn = get_db()
    try:
        vel_data = _shopify_velocity(conn, days=60)
        mp_stock = _get_mp_stock(conn)
        formulas = _get_formulas(conn)
        if not formulas:
            return jsonify({'n': 0, 'criticos': 0})
        _, alerts = _project_stock(
            conn, vel_data['prod_velocity'], formulas, mp_stock, []
        )
        criticos = len([a for a in alerts if a['nivel'] == 'critico'])
        return jsonify({'n': len(alerts), 'criticos': criticos})
    except Exception as e:
        return jsonify({'n': 0, 'error': str(e)})


@bp.route('/api/programacion/debug-mps')
def prog_debug_mps():
    """Debug: cross-reference mp_stock entries vs formula_items material_ids."""
    if not _auth():
        return jsonify({'error': 'no auth'}), 401
    conn = get_db()

    # MP stock from movimientos
    mp_stock = _get_mp_stock(conn)

    # All material_ids used in formulas
    formula_mids = conn.execute(
        "SELECT DISTINCT material_id, material_nombre FROM formula_items ORDER BY material_id"
    ).fetchall()

    matched   = []
    unmatched = []
    for mid, nombre in formula_mids:  # nombre = material_nombre
        # Try: unlimited → ID → exact name → norm name → alias
        nombre_str = str(nombre or '')
        if _is_unlimited_mp(nombre_str):
            stock = float('inf')
            match_via = 'unlimited'
        elif mid in mp_stock:
            stock = mp_stock[mid]
            match_via = 'id'
        else:
            nombre_exact = nombre_str.strip().upper()
            if nombre_exact in mp_stock:
                stock = mp_stock[nombre_exact]
                match_via = 'nombre_exact'
            else:
                nombre_norm = _norm_mp_name(nombre_str)
                if nombre_norm in mp_stock:
                    stock = mp_stock[nombre_norm]
                    match_via = 'nombre_norm'
                else:
                    alias_key = _MP_NAME_ALIAS.get(nombre_norm) or _MP_NAME_ALIAS.get(nombre_exact)
                    if alias_key and alias_key in mp_stock:
                        stock = mp_stock[alias_key]
                        match_via = 'alias'
                    else:
                        stock = None
                        match_via = None

        if stock is not None:
            matched.append({'material_id': mid, 'nombre': nombre,
                            'stock_g': round(stock, 1), 'match_via': match_via})
        else:
            unmatched.append({'material_id': mid, 'nombre': nombre})

    # Sample mp_stock keys (first 20)
    sample_stock_keys = sorted(mp_stock.keys())[:20]

    # Movimientos table row count
    n_mov = conn.execute("SELECT COUNT(*) FROM movimientos").fetchone()[0]

    # Check if movimientos has any 'entrada' tipo
    n_entradas = conn.execute(
        "SELECT COUNT(*) FROM movimientos WHERE tipo IN ('entrada','Entrada','ENTRADA')"
    ).fetchone()[0]

    # Search mp_stock for critical keywords
    keywords = ['AGUA', 'ALOE', 'ARGAN', 'JOJOBA', 'ASCORBICO', 'FERULICO',
                'PANTENOL', 'CETILICO', 'CETEARIL', 'ROSA MOSQUETA',
                'ACETIL', 'ACETYL', 'HIALURONICO',
                'SILICONA', 'EZ', 'REGALIZ', 'GLYCYRRHIZA', 'LICORICE',
                'CENTELLA', 'PROPILEN', 'CARBOPOL', 'CAFEINA', 'CERAMIDA',
                'BETAGLUCAN', 'BACKUCHIOL', 'NIACINAMIDA', 'RETINOL']
    keyword_hits = {}
    for kw in keywords:
        hits = [k for k in mp_stock if kw in k]
        if hits:
            keyword_hits[kw] = hits[:5]

    # Show normalized form of unmatched names for debugging
    unmatched_with_norm = []
    for item in unmatched:
        norm_key = _norm_mp_name(item['nombre'])
        in_stock = norm_key in mp_stock
        unmatched_with_norm.append({**item, 'norm_key': norm_key, 'norm_in_stock': in_stock})

    return jsonify({
        'mp_stock_total_entries': len(mp_stock),
        'mp_stock_sample_keys': sample_stock_keys,
        'formula_items_distinct_materials': len(formula_mids),
        'matched_count': len(matched),
        'unmatched_count': len(unmatched),
        'unmatched': unmatched_with_norm[:30],
        'matched_sample': matched[:10],
        'movimientos_total_rows': n_mov,
        'movimientos_entradas': n_entradas,
        'keyword_hits_in_stock': keyword_hits,
    })


@bp.route('/api/programacion/debug-mp-check/<producto>')
def prog_debug_mp_check(producto):
    """Debug: muestra el mp_check completo para un producto específico."""
    if not _auth():
        return jsonify({'error': 'no auth'}), 401
    conn = get_db()
    mp_stock = _get_mp_stock(conn)
    formulas = _get_formulas(conn)

    prod_key = None
    for k in formulas:
        if k.upper() == producto.upper() or producto.upper() in k.upper():
            prod_key = k
            break

    if not prod_key:
        available = list(formulas.keys())
        return jsonify({'error': f'Producto no encontrado', 'disponibles': available[:20]}), 404

    data = formulas[prod_key]
    lote_kg = data.get('lote_size_kg') or 1.0
    items = data.get('items', [])
    items_with_qty = [i for i in items if i.get('cantidad_g_por_lote', 0) > 0]

    result = []
    for item in items_with_qty:
        mid = str(item['material_id']).strip()
        nombre_raw = str(item.get('material_nombre', '')).strip()
        needed_g = float(item['cantidad_g_por_lote'])

        # Mirror exact lookup logic from _project_stock
        if _is_unlimited_mp(nombre_raw):
            available_g = float('inf')
            match_via = 'unlimited'
        elif mid in mp_stock:
            available_g = mp_stock[mid]
            match_via = 'id'
        else:
            nombre_exact = nombre_raw.upper()
            if nombre_exact in mp_stock:
                available_g = mp_stock[nombre_exact]
                match_via = 'nombre_exact'
            else:
                nombre_norm = _norm_mp_name(nombre_raw)
                if nombre_norm in mp_stock:
                    available_g = mp_stock[nombre_norm]
                    match_via = 'nombre_norm'
                else:
                    alias_key = _MP_NAME_ALIAS.get(nombre_norm) or _MP_NAME_ALIAS.get(nombre_exact)
                    if alias_key and alias_key in mp_stock:
                        available_g = mp_stock[alias_key]
                        match_via = f'alias→{alias_key}'
                    else:
                        available_g = 0
                        match_via = 'NOT_FOUND'

        deficit_g = 0 if available_g == float('inf') else max(0, needed_g - available_g)
        ok = deficit_g < 1
        result.append({
            'material_id': mid,
            'nombre': nombre_raw,
            'needed_g': round(needed_g, 1),
            'available_g': '∞' if available_g == float('inf') else round(available_g, 1),
            'deficit_g': round(deficit_g, 1),
            'ok': ok,
            'match_via': match_via,
        })

    result.sort(key=lambda x: (x['ok'], -x['deficit_g']))  # failing first
    failing = [r for r in result if not r['ok']]
    return jsonify({
        'producto': prod_key,
        'lote_kg': lote_kg,
        'total_ingredientes': len(result),
        'ingredientes_faltantes': len(failing),
        'can_produce': len(failing) == 0,
        'failing_first': result,
    })


# ─── MP Bridge — admin endpoints ─────────────────────────────────────────────

from contextlib import contextmanager as _contextmanager  # noqa: E402


@_contextmanager
def _db():
    """FIX 10-jul · las 4 rutas de mp-bridge usaban `with _db() as conn` pero `_db` NUNCA se definió
    → NameError → 500 (gestión de puentes muerta · no se podían separar códigos mal puenteados como
    Panthenol polvo↔líquido). Cede la conexión per-request (get_db); el commit lo hacen los writers."""
    yield get_db()


@bp.route('/api/programacion/mp-bridge', methods=['GET'])
def mp_bridge_list():
    """List all bridge mappings (active and inactive)."""
    with _db() as conn:
        rows = conn.execute("""
            SELECT id, formula_material_id, formula_material_nombre,
                   bodega_material_id, bodega_material_nombre, bodega_inci,
                   notas, activo, creado_en
            FROM mp_formula_bridge
            ORDER BY formula_material_nombre NULLS LAST
        """).fetchall()
        keys = ['id', 'formula_material_id', 'formula_material_nombre',
                'bodega_material_id', 'bodega_material_nombre', 'bodega_inci',
                'notas', 'activo', 'creado_en']
        return jsonify([dict(zip(keys, r)) for r in rows])


@bp.route('/api/programacion/mp-bridge', methods=['POST'])
def mp_bridge_add():
    """Add or update a bridge mapping.

    Body JSON: {
        formula_material_id, formula_material_nombre,
        bodega_material_id, bodega_material_nombre, bodega_inci, notas
    }
    """
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    data = request.get_json(force=True) or {}
    fid   = str(data.get('formula_material_id', '') or '').strip()
    fname = str(data.get('formula_material_nombre', '') or '').strip()
    bid   = str(data.get('bodega_material_id', '') or '').strip()
    bname = str(data.get('bodega_material_nombre', '') or '').strip()
    binci = str(data.get('bodega_inci', '') or '').strip()
    notas = str(data.get('notas', '') or '').strip()

    if not fid or not bid:
        return jsonify({'error': 'formula_material_id y bodega_material_id son obligatorios'}), 400

    with _db() as conn:
        conn.execute("""
            INSERT INTO mp_formula_bridge
                (formula_material_id, formula_material_nombre,
                 bodega_material_id, bodega_material_nombre, bodega_inci, notas, activo)
            VALUES (?, ?, ?, ?, ?, ?, 1)
            ON CONFLICT(formula_material_id, bodega_material_id)
            DO UPDATE SET
                formula_material_nombre = excluded.formula_material_nombre,
                bodega_material_nombre  = excluded.bodega_material_nombre,
                bodega_inci             = excluded.bodega_inci,
                notas                   = excluded.notas,
                activo                  = 1
        """, (fid, fname or None, bid, bname or None, binci or None, notas or None))
        conn.commit()
    return jsonify({'ok': True, 'formula_material_id': fid, 'bodega_material_id': bid})


@bp.route('/api/programacion/mp-bridge/<int:bridge_id>', methods=['DELETE'])
def mp_bridge_delete(bridge_id):
    """Desactiva un puente (activo=0) · AUDITADO.

    Un puente decide de QUÉ código sale el material cuando se produce, así que quitarlo cambia
    el descuento del inventario -- es una mutación regulada y hasta el 2-ago se hacía sin dejar
    rastro. Lo vi al desactivar el puente 184 (`MP00181 → MP00176`), que a su vez alguien había
    creado en junio sin que quedara constancia: por eso nadie sabía que existía.
    """
    _u = session.get('compras_user', '')
    if not _u:
        return jsonify({'error': 'No autorizado'}), 401
    # Quitar un puente cambia DE QUE CODIGO sale el material al producir · no lo hace un operario.
    from config import puede_archivar as _puede_arch
    if not _puede_arch(_u):
        return jsonify({'error': 'Los operarios no desactivan puentes de material',
                        'detalle': 'Pediselo a compras o a un administrador.'}), 403
    conn = get_db(); c = conn.cursor()
    r = c.execute("SELECT formula_material_id, bodega_material_id, COALESCE(activo,1), "
                  "COALESCE(notas,'') FROM mp_formula_bridge WHERE id=?", (bridge_id,)).fetchone()
    if not r:
        return jsonify({'error': 'ese puente no existe'}), 404
    cur = c.execute("UPDATE mp_formula_bridge SET activo=0 WHERE id=? AND COALESCE(activo,1)=1",
                    (bridge_id,))
    if (cur.rowcount or 0) != 1:
        return jsonify({'ok': True, 'id': bridge_id, 'activo': 0, 'aviso': 'ya estaba inactivo'})
    audit_log(c, usuario=_u, accion='DESACTIVAR_PUENTE_MP', tabla='mp_formula_bridge',
              registro_id=str(bridge_id),
              antes={'formula_material_id': r[0], 'bodega_material_id': r[1],
                     'activo': int(r[2] or 0), 'notas': r[3][:200]},
              despues={'activo': 0, 'efecto': 'la fórmula deja de resolverse a %s' % r[1]})
    conn.commit()
    return jsonify({'ok': True, 'id': bridge_id, 'activo': 0,
                    'que_cambia': ('Las fórmulas que pedían %s dejan de sacar el material de %s. '
                                   'Queda en audit_log: es reversible.' % (r[0], r[1]))})


@bp.route('/api/programacion/mp-bridge/unmatched', methods=['GET'])
def mp_bridge_unmatched():
    """Return formula_items that cannot be matched to any movimientos entry.

    Useful for populating the bridge table: shows what still needs linking,
    along with candidate bodega materials (fuzzy name match by keywords).
    """
    with _db() as conn:
        mp_stock = _get_mp_stock(conn)

        # All bridge mappings already in place (formula_material_id → bodega_material_id)
        bridged_fids = set(r[0] for r in conn.execute(
            "SELECT formula_material_id FROM mp_formula_bridge WHERE activo=1"
        ).fetchall())

        # Fetch distinct formula items (one entry per material_id)
        items = conn.execute("""
            SELECT DISTINCT material_id, material_nombre
            FROM formula_items
            WHERE material_id IS NOT NULL AND material_id != ''
            ORDER BY material_nombre
        """).fetchall()

        # Fetch all bodega materials for candidate suggestions
        bodega_mats = conn.execute("""
            SELECT DISTINCT material_id, material_nombre
            FROM movimientos
            WHERE material_id IS NOT NULL AND material_id != ''
              AND material_nombre IS NOT NULL AND material_nombre != ''
            ORDER BY material_nombre
        """).fetchall()

        unmatched = []
        for mid, nombre in items:
            mid = str(mid or '').strip()
            nombre_raw = str(nombre or '').strip()

            # Skip already bridged
            if mid in bridged_fids:
                continue
            # Skip unlimited MPs
            if _is_unlimited_mp(nombre_raw):
                continue
            # Check if already matched via stock dict
            nombre_exact = nombre_raw.upper()
            nombre_norm  = _norm_mp_name(nombre_raw)
            alias_key    = _MP_NAME_ALIAS.get(nombre_norm) or _MP_NAME_ALIAS.get(nombre_exact)

            already_matched = (
                mid in mp_stock
                or nombre_exact in mp_stock
                or nombre_norm in mp_stock
                or (alias_key and alias_key in mp_stock)
            )
            if already_matched:
                continue

            # Build candidate suggestions: bodega materials whose normalized name
            # shares at least one 4-char keyword with the formula material name
            formula_keywords = set(w for w in nombre_norm.split() if len(w) >= 4)
            candidates = []
            for bid, bname in bodega_mats:
                bname_norm = _norm_mp_name(str(bname or ''))
                bname_words = set(w for w in bname_norm.split() if len(w) >= 4)
                shared = formula_keywords & bname_words
                if shared:
                    candidates.append({
                        'material_id': bid,
                        'material_nombre': bname,
                        'shared_keywords': sorted(shared),
                        'score': len(shared)
                    })
            candidates.sort(key=lambda x: -x['score'])

            unmatched.append({
                'formula_material_id':     mid,
                'formula_material_nombre': nombre_raw,
                'candidates':              candidates[:5]  # top 5 suggestions
            })

        return jsonify({
            'total_unmatched': len(unmatched),
            'unmatched': unmatched
        })


# ─── Producciones con faltantes (vista simple para Luis Enrique) ─────────
# Sebastian 5-may-2026: jefe de producción quiere UN solo flujo.
#   1. Selector horizonte (semana, 15d, 1m, 2m, 3m, 6m, 1 año)
#   2. Tabla de producciones programadas en ese horizonte
#   3. Por cada producción: ver MP+MEE faltantes
#   4. Botón "Solicitar TODO faltante" → bulk OC por proveedor
#
# Reutiliza:
#   - produccion_programada (eventos programados)
#   - formula_items (MP por producto)
#   - sku_mee_config (MEE por producto)
#   - maestro_mps + mp_lead_time_config (proveedor sugerido MP)
#   - maestro_mee + mee_lead_time_config (proveedor sugerido MEE)
#
# Excluye producciones con inventario_descontado_at != NULL (ya consumieron).

@bp.route('/api/programacion/producciones-faltantes', methods=['GET'])
def producciones_faltantes():
    """Producciones programadas en horizonte + agregado de MP/MEE faltantes.

    Query params:
      dias: int 7-365 (default 60)

    Returns:
      {
        horizonte_dias: int,
        producciones: [
          {id, producto, fecha, lotes, cantidad_kg,
           mps_necesarias: [{codigo_mp, nombre, necesario_g}],
           mees_necesarios: [{codigo, descripcion, tipo, necesario_unidades}]
          }
        ],
        faltantes_mps: [
          {codigo_mp, nombre, necesario_total_g, stock_actual_g, faltante_g,
           proveedor_sugerido}
        ],
        faltantes_mees: [
          {codigo, descripcion, tipo, necesario_total_u, stock_actual_u,
           faltante_u, proveedor_sugerido}
        ],
        resumen: {n_producciones, n_mps_faltantes, n_mees_faltantes,
                  n_proveedores_unicos}
      }
    """
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    try:
        dias = max(7, min(int(request.args.get('dias', 60)), 365))
    except (ValueError, TypeError):
        dias = 60

    # Sebastián 9-may-2026: las producciones programadas que pasaron pero
    # nunca arrancaron (sin inicio_real_at, sin descontar) ensucian el panel
    # con basura vieja ("Mar 28 ya pasó", "Lun 4 ya pasó", ...) que ya no
    # se va a producir. Antes del fix se mezclaba con lo real.
    #
    # Ahora se filtra:
    #   - REALIZADAS pasadas (con inicio_real_at o desc_at): SIEMPRE se
    #     muestran independiente del horizonte → trazabilidad histórica.
    #   - PENDIENTES pasadas: solo se muestran si fecha >= hoy - atrasadas_max_dias
    #     (default 7d). Una atrasada de >7d sin arrancar es ruido.
    #   - Si el usuario quiere ver TODAS las atrasadas pendientes (para
    #     limpiarlas/cancelarlas), pasa ?atrasadas_max_dias=999 desde el
    #     toggle "Mostrar atrasadas viejas" del frontend.
    try:
        atrasadas_max_dias = max(0, min(int(request.args.get('atrasadas_max_dias', 7)), 999))
    except (ValueError, TypeError):
        atrasadas_max_dias = 7

    conn = get_db(); c = conn.cursor()
    from datetime import date, timedelta as _td
    hoy = date.today()
    cutoff = (hoy + _td(days=dias)).isoformat()
    # Ventana pasada amplia (14d) solo para que las realizadas viejas SÍ aparezcan.
    # Las pendientes-pasadas se filtran por separado abajo.
    pasado_dias = 14
    past_window = (hoy - _td(days=pasado_dias)).isoformat()
    # Threshold para pendientes-pasadas (atrasadas que no arrancaron)
    atrasadas_cutoff = (hoy - _td(days=atrasadas_max_dias)).isoformat()

    # 1. Cargar producciones programadas pendientes Y realizadas en ventana.
    # Sebastián 9-may-2026: condición compuesta para evitar ruido de atrasadas
    # viejas pendientes. La pasada-pendiente (sin inicio_real_at, sin desc_at)
    # solo aparece si fecha >= atrasadas_cutoff (default hoy-7d).
    # La REALIZADA (tiene inicio_real_at o desc_at) siempre aparece dentro de
    # la ventana past_window (14d hacia atrás · trazabilidad reciente).
    # La FUTURA (>= hoy) siempre aparece hasta el cutoff.
    try:
        c.execute("""
            SELECT pp.id, pp.producto, pp.fecha_programada,
                   COALESCE(pp.lotes, 1), COALESCE(pp.cantidad_kg, 0),
                   COALESCE(fh.lote_size_kg, 0) as lote_size_kg,
                   COALESCE(pp.area_id, 0) as area_id,
                   COALESCE(ap.codigo, '') as area_codigo,
                   COALESCE(ap.nombre, '') as area_nombre,
                   COALESCE(LOWER(pp.estado), 'pendiente') as estado_norm,
                   COALESCE(pp.inicio_real_at, '') as inicio_real_at,
                   COALESCE(pp.fin_real_at, '') as fin_real_at,
                   COALESCE(pp.inventario_descontado_at, '') as desc_at
            FROM produccion_programada pp
            LEFT JOIN formula_headers fh
                   ON UPPER(TRIM(fh.producto_nombre)) = UPPER(TRIM(pp.producto))
            LEFT JOIN areas_planta ap ON ap.id = pp.area_id
            WHERE LOWER(COALESCE(pp.estado, '')) != 'cancelado'
              AND pp.fecha_programada >= ?
              AND pp.fecha_programada <= ?
              AND (
                    -- Realizada: con inicio_real_at o desc_at → siempre incluir
                    COALESCE(pp.inicio_real_at, '') != ''
                 OR COALESCE(pp.inventario_descontado_at, '') != ''
                    -- Futura o atrasada reciente (≤ atrasadas_max_dias)
                 OR pp.fecha_programada >= ?
              )
            ORDER BY pp.fecha_programada ASC
        """, (past_window, cutoff, atrasadas_cutoff))
        prod_rows = c.fetchall()
    except sqlite3.OperationalError:
        # Fallback si areas_planta no existe (esquema legacy)
        c.execute("""
            SELECT pp.id, pp.producto, pp.fecha_programada,
                   COALESCE(pp.lotes, 1), COALESCE(pp.cantidad_kg, 0),
                   COALESCE(fh.lote_size_kg, 0) as lote_size_kg,
                   0, '', '',
                   COALESCE(LOWER(pp.estado), 'pendiente'),
                   COALESCE(pp.inicio_real_at, ''),
                   COALESCE(pp.fin_real_at, ''),
                   COALESCE(pp.inventario_descontado_at, '')
            FROM produccion_programada pp
            LEFT JOIN formula_headers fh
                   ON UPPER(TRIM(fh.producto_nombre)) = UPPER(TRIM(pp.producto))
            WHERE LOWER(COALESCE(pp.estado, '')) != 'cancelado'
              AND pp.fecha_programada >= ?
              AND pp.fecha_programada <= ?
              AND (
                    COALESCE(pp.inicio_real_at, '') != ''
                 OR COALESCE(pp.inventario_descontado_at, '') != ''
                 OR pp.fecha_programada >= ?
              )
            ORDER BY pp.fecha_programada ASC
        """, (past_window, cutoff, atrasadas_cutoff))
        prod_rows = c.fetchall()

    # 2. Cargar formulas (codigo_mp -> [nombre, cantidad_g_por_lote, porcentaje])
    formulas = {}
    for r in c.execute("""
        SELECT producto_nombre, material_id, material_nombre,
               COALESCE(porcentaje, 0), COALESCE(cantidad_g_por_lote, 0)
        FROM formula_items
    """).fetchall():
        prod = (r[0] or '').strip().upper()
        formulas.setdefault(prod, []).append({
            'codigo_mp': r[1] or '',
            'nombre': r[2] or '',
            'porcentaje': float(r[3] or 0),
            'g_por_lote': float(r[4] or 0),
        })

    # 3. Cargar sku_mee_config (producto/sku -> [mee_codigo, cantidad_por_unidad, tipo])
    mee_por_producto = {}
    try:
        for r in c.execute("""
            SELECT s.sku_codigo, s.mee_codigo,
                   COALESCE(s.cantidad_por_unidad, 1),
                   COALESCE(s.componente_tipo, 'envase'),
                   COALESCE(m.descripcion, '') as descripcion
            FROM sku_mee_config s
            LEFT JOIN maestro_mee m ON m.codigo = s.mee_codigo
            WHERE COALESCE(s.aplica, 1) = 1
        """).fetchall():
            sku = (r[0] or '').strip().upper()
            mee_por_producto.setdefault(sku, []).append({
                'mee_codigo': r[1] or '',
                'cantidad_por_unidad': float(r[2] or 1),
                'tipo': r[3] or 'envase',
                'descripcion': r[4] or '',
            })
    except sqlite3.OperationalError:
        # Tabla no existe (esquema antiguo) · seguir sin MEE
        mee_por_producto = {}

    # 4. Cargar volumen unitario por producto (ml por unidad envasada)
    volumen_por_producto = {}
    try:
        for r in c.execute("""
            SELECT producto_nombre, COALESCE(volumen_ml, 0)
            FROM volumen_unitario_producto WHERE COALESCE(activo,1)=1
        """).fetchall():
            volumen_por_producto[(r[0] or '').strip().upper()] = float(r[1] or 0)
    except sqlite3.OperationalError:
        pass
    # Si no hay tabla volumen_unitario, intentar producto_presentaciones
    if not volumen_por_producto:
        try:
            for r in c.execute("""
                SELECT producto_nombre, MAX(COALESCE(volumen_ml, 0))
                FROM producto_presentaciones
                WHERE COALESCE(activo,1)=1
                GROUP BY producto_nombre
            """).fetchall():
                volumen_por_producto[(r[0] or '').strip().upper()] = float(r[1] or 0)
        except sqlite3.OperationalError:
            pass

    # FASE 2 · 27-may-2026 PM · cargar TODAS las presentaciones por producto
    # cuando hay >1 (caso variantes 30ml/15ml/10ml) · cálculo correcto sumando
    # envases por presentación con ratio histórico Shopify 90d.
    # Estructura: presentaciones_por_producto[producto_norm] = [
    #   {'codigo','volumen_ml','envase_codigo','sku_shopify','factor_g_por_unidad'}, ...
    # ]
    presentaciones_por_producto = {}
    try:
        for r in c.execute("""
            SELECT producto_nombre, presentacion_codigo,
                   COALESCE(volumen_ml,0), COALESCE(envase_codigo,''),
                   COALESCE(sku_shopify,''),
                   COALESCE(factor_g_por_unidad, volumen_ml, 0),
                   COALESCE(ventas_mes_referencia, 0)
            FROM producto_presentaciones
            WHERE COALESCE(activo,1)=1 AND COALESCE(volumen_ml,0) > 0
        """).fetchall():
            pn = (r[0] or '').strip().upper()
            if not pn:
                continue
            presentaciones_por_producto.setdefault(pn, []).append({
                'codigo': r[1],
                'volumen_ml': float(r[2] or 0),
                'envase_codigo': (r[3] or '').strip(),
                'sku_shopify': (r[4] or '').strip(),
                'factor_g_por_unidad': float(r[5] or r[2] or 0),
                'ventas_mes_referencia': float(r[6] or 0),
            })
    except sqlite3.OperationalError:
        pass

    # Ratio histórico Shopify por presentación (últimos 180d · 6m) Sebastián
    # 27-may-2026 PM · "si lanzas la busqueda de ventas en 6 meses sabras que
    # se vendio no puede se 50 50". Ampliado de 90d para capturar SKUs B2B
    # con cadencia mensual o trimestral.
    # Si Shopify sync no está activo o no hay data → ratio uniforme (1/N).
    ventas_por_sku_90d = {}
    try:
        from datetime import datetime as _dt90, timedelta as _td90
        _cutoff_90d = (_dt90.utcnow() - _td90(hours=5) - _td90(days=180)).date().isoformat()
        import json as _json_sk
        rows_sho = c.execute(
            """SELECT sku_items FROM animus_shopify_orders
               WHERE COALESCE(creado_en,'') >= ? AND sku_items IS NOT NULL AND sku_items != ''""",
            (_cutoff_90d,)
        ).fetchall()
        for (it,) in rows_sho:
            try:
                items = _json_sk.loads(it) if it else []
                if not isinstance(items, list):
                    continue
                for li in items:
                    sk = (li.get('sku') or '').strip()
                    qty = int(li.get('qty') or 0)
                    if sk and qty > 0:
                        ventas_por_sku_90d[sk] = ventas_por_sku_90d.get(sk, 0) + qty
            except Exception:
                continue
    except sqlite3.OperationalError:
        pass

    # M58 (5-jul) · ventas 90d por (producto, VOLUMEN): matchea SKU→producto+tamaño (sku_producto_map) para
    # repartir multi-presentación (15 vs 30ml) por VENTAS REALES aunque la presentación no traiga sku_shopify.
    # Antes caía a uniforme (50/50) → sobre-compra del tamaño que casi no se vende. Corazón del "todo está mal".
    _ventas_up = {}
    for _k, _v in ventas_por_sku_90d.items():
        _ku = str(_k).strip().upper()
        _ventas_up[_ku] = _ventas_up.get(_ku, 0) + _v
    sku_vol_ventas = {}   # producto_upper -> {volumen_int: uds}
    try:
        for _sk, _pn, _vm in c.execute("SELECT UPPER(TRIM(sku)), producto_nombre, COALESCE(volumen_ml,0) "
                                       "FROM sku_producto_map WHERE COALESCE(activo,1)=1").fetchall():
            if not _sk:
                continue
            _u = _ventas_up.get(str(_sk).strip().upper(), 0)
            if _u <= 0:
                continue
            _dv = sku_vol_ventas.setdefault((_pn or '').strip().upper(), {})
            _vk = int(round(float(_vm or 0)))
            _dv[_vk] = _dv.get(_vk, 0) + _u
    except Exception:
        pass

    def _ratio_presentaciones(producto_norm):
        """Devuelve dict {codigo_presentacion: ratio_del_KG_0_a_1}. El ratio es la porción del BULK (kg) que va a
        cada presentación = PESADO POR VOLUMEN: unidades_vendidas × ml, normalizado. Una unidad de 30ml se lleva
        3× el bulk de una de 10ml, así que aunque se vendan iguales unidades el 30ml se lleva más kg (bug M58/5-jul
        cazado por Sebastián: un lote de 90kg con 1000 uds de 10ml → 80kg quedan para 30ml = 2666, no 1400).
        Unidades vendidas por prioridad: 1) ventas_mes_referencia manual, 2) Shopify por volumen (SKU), 3) Shopify
        por sku_shopify de la presentación, 4) uniforme."""
        pres = presentaciones_por_producto.get(producto_norm, [])
        if not pres:
            return {}
        if len(pres) == 1:
            return {pres[0]['codigo']: 1.0}
        # (a) UNIDADES vendidas por presentación (según prioridad)
        # Misma regla que el reparto del lote y el del trail: una sola funcion, tres usos (M45).
        unidades = _unidades_por_presentacion(
            [{'cod': p['codigo'], 'sku': p.get('sku_shopify'), 'vol': p.get('volumen_ml'),
              'override': p.get('ventas_mes_referencia')} for p in pres],
            {str(k).strip().upper(): v for k, v in (ventas_por_sku_90d or {}).items()},
            sku_vol_ventas.get(producto_norm, {}) or {})
        # (b) PESAR POR VOLUMEN → porción del kg (bulk) de cada presentación
        pesos = {p['codigo']: unidades.get(p['codigo'], 0) * float(p.get('volumen_ml') or 0) for p in pres}
        total_peso = sum(pesos.values())
        if total_peso > 0:
            return {cod: (pw / total_peso) for cod, pw in pesos.items()}
        return {p['codigo']: 1.0 / len(pres) for p in pres}

    # 5. Cargar stock MP (canonical helper)
    stock_mp = _get_mp_stock(conn)

    # 6. Cargar stock MEE
    # P0-4 23-may-PM · auditoría agente Stock · antes leía maestro_mee
    # .stock_actual directo (cache que puede drift) · ahora usa el helper
    # canónico _get_mee_stock que suma movimientos_mee.
    stock_mee = _get_mee_stock(conn)

    # 7. Cargar info MP (nombre canonico + proveedor sugerido)
    mp_info = {}
    try:
        for r in c.execute("""
            SELECT mm.codigo_mp,
                   COALESCE(mm.nombre_comercial, mm.nombre_inci, mm.codigo_mp) as nombre,
                   COALESCE(NULLIF(TRIM(mlt.proveedor_principal),''), mm.proveedor, '') as prov
            FROM maestro_mps mm
            LEFT JOIN mp_lead_time_config mlt ON mlt.material_id = mm.codigo_mp
            WHERE COALESCE(mm.activo, 1) = 1
        """).fetchall():
            mp_info[r[0]] = {'nombre': r[1] or r[0], 'proveedor': (r[2] or '').strip()}
    except sqlite3.OperationalError:
        pass

    # 8. Cargar info MEE (proveedor sugerido)
    mee_info = {}
    try:
        for r in c.execute("""
            SELECT mm.codigo,
                   COALESCE(mm.descripcion, mm.codigo) as descripcion,
                   COALESCE(cfg.proveedor_principal, mm.proveedor, '') as prov
            FROM maestro_mee mm
            LEFT JOIN mee_lead_time_config cfg ON cfg.mee_codigo = mm.codigo
        """).fetchall():
            mee_info[r[0]] = {
                'descripcion': r[1] or r[0],
                'proveedor': (r[2] or '').strip(),
            }
    except sqlite3.OperationalError:
        pass

    # 9. Por cada producción, calcular MP y MEE necesarios
    producciones_out = []
    consumo_mp_agregado = {}   # codigo_mp -> g_total
    consumo_mee_agregado = {}  # mee_codigo -> unidades_total
    _claves_vistas = set()     # anti-clon · ver _clave_clon abajo
    productos_sin_volumen = set()  # con MEE configurado pero sin volumen_ml
    hoy_iso = hoy.isoformat()
    for row in prod_rows:
        # Sebastian 5-may-2026: unpack soporta ambos esquemas (con/sin areas_planta)
        # Sebastian 8-may-2026: nuevo campo `desc_at` (inventario_descontado_at)
        # para detectar realizadas.
        desc_at = ''
        if len(row) >= 13:
            (pid, producto, fecha, lotes, cant_kg_explicita, lote_size,
             area_id, area_codigo, area_nombre,
             estado_norm, inicio_real_at, fin_real_at, desc_at) = row
        elif len(row) >= 12:
            (pid, producto, fecha, lotes, cant_kg_explicita, lote_size,
             area_id, area_codigo, area_nombre,
             estado_norm, inicio_real_at, fin_real_at) = row
        else:
            pid, producto, fecha, lotes, cant_kg_explicita, lote_size = row[:6]
            area_id, area_codigo, area_nombre = 0, '', ''
            estado_norm, inicio_real_at, fin_real_at = 'pendiente', '', ''
        producto_norm = (producto or '').strip().upper()
        lotes = int(lotes or 1)
        cant_kg_total = float(cant_kg_explicita or 0) or (lotes * float(lote_size or 0))

        # Sebastián 8-may-2026: clasificación visual + lógica MP separadas.
        # · Realizada: TERMINADA (fin_real_at o estado=completado)
        # · En proceso: arrancó pero no terminó (inicio_real_at sin fin · o
        #   descontada sin fin)
        # · Atrasada: fecha pasó sin arrancar y sin descontar · sigue pendiente
        # · Pendiente: futura sin arrancar · caso normal
        # MPs/MEEs faltantes: regla por separado · NO contar si ya hay descuento
        # registrado (desc_at set) · esos MPs ya salieron del stock.
        es_realizada = bool(fin_real_at) or estado_norm == 'completado'
        es_en_proceso = (bool(inicio_real_at) or bool(desc_at)) and not es_realizada
        es_pasada = (fecha or '') < hoy_iso
        es_atrasada = es_pasada and not es_realizada and not es_en_proceso
        # Dedup anti-clon · si el sync de Calendar insertó un duplicado
        # EXACTO (mismo producto, fecha, lotes y kg), solo el primero cuenta
        # para el agregado de faltantes · si no, se pediría comprar el doble.
        # Clave EXACTA (no la heurística de ventana de 7d, que daría falsos
        # positivos): el scheduling real no repite lo idéntico el mismo día.
        _clave_clon = (producto_norm, (fecha or '')[:10], lotes, round(cant_kg_total, 3))
        es_clon = _clave_clon in _claves_vistas
        if not es_clon:
            _claves_vistas.add(_clave_clon)
        # Solo sumar al consumo si NO se ha descontado, aún hay que hacerla
        # y NO es un clon exacto ya contado.
        cuenta_para_faltantes = not bool(desc_at) and not es_realizada and not es_clon

        if es_realizada:
            estado_display = 'realizada'
        elif es_en_proceso:
            estado_display = 'en_proceso'
        elif es_atrasada:
            estado_display = 'atrasada'
        else:
            estado_display = 'pendiente'

        # MPs necesarias (siempre se calculan para mostrar en modal, pero solo
        # se acumulan al global de faltantes si la producción aún consume stock)
        mps_nec = []
        for fi in formulas.get(producto_norm, []):
            g_total = float(fi['g_por_lote'] or 0) * lotes
            if g_total <= 0 and cant_kg_total > 0:
                g_total = (fi['porcentaje'] / 100.0) * cant_kg_total * 1000.0
            if g_total <= 0:
                continue
            mps_nec.append({
                'codigo_mp': fi['codigo_mp'],
                'nombre': fi['nombre'],
                'necesario_g': round(g_total, 2),
            })
            cod = (fi['codigo_mp'] or '').strip()
            if cod and cuenta_para_faltantes:
                consumo_mp_agregado[cod] = consumo_mp_agregado.get(cod, 0) + g_total

        # MEE necesarios · 2 caminos:
        #  A) Producto con VARIANTES (>1 presentación en producto_presentaciones):
        #     calcular envases por presentación usando ratio Shopify 90d.
        #     Cada presentación tiene su volumen_ml y su envase_codigo propios.
        #  B) Producto SIN variantes: comportamiento clásico (sku_mee_config +
        #     volumen_unitario_producto único).
        # FASE 2 · Sebastián 27-may-2026 PM · fix para LIP SERUM tipo 30ml+15ml.
        unidades_envasadas = 0
        mees_nec = []
        presentaciones_prod = presentaciones_por_producto.get(producto_norm, [])
        usar_variantes = (len(presentaciones_prod) > 1 and cant_kg_total > 0)

        if usar_variantes:
            ratios = _ratio_presentaciones(producto_norm)
            unidades_total_calc = 0
            for p in presentaciones_prod:
                ratio = ratios.get(p['codigo'], 0)
                vol_p = p['volumen_ml']
                if vol_p <= 0 or ratio <= 0:
                    continue
                # kg que va a esta presentación · luego ml · luego unidades
                kg_p = cant_kg_total * ratio
                un_p = int(round((kg_p * 1000.0) / vol_p))
                unidades_total_calc += un_p
                env_cod = p['envase_codigo']
                if env_cod and un_p > 0:
                    _desc_env = (mee_info.get(env_cod, {}) or {}).get('descripcion', env_cod) if mee_info else env_cod
                    mees_nec.append({
                        'codigo': env_cod,
                        'descripcion': _desc_env,
                        'tipo': 'envase',
                        'necesario_unidades': un_p,
                        'presentacion': p['codigo'],
                        'ratio_pct': round(ratio * 100, 1),
                    })
                    if cuenta_para_faltantes:
                        cod_norm = env_cod.strip().upper()
                        consumo_mee_agregado[cod_norm] = consumo_mee_agregado.get(cod_norm, 0) + un_p
            unidades_envasadas = unidades_total_calc
            # Además, agregar OTROS mees configurados en sku_mee_config para este
            # producto (típicamente tapas/etiquetas que comparten todas las
            # presentaciones · cant_por_unidad * unidades_envasadas total)
            for me in mee_por_producto.get(producto_norm, []):
                cant_total = unidades_envasadas * float(me['cantidad_por_unidad'] or 1)
                mees_nec.append({
                    'codigo': me['mee_codigo'],
                    'descripcion': me['descripcion'],
                    'tipo': me['tipo'],
                    'necesario_unidades': round(cant_total, 0),
                })
                cod_mee = (me['mee_codigo'] or '').strip().upper()
                if cod_mee and cuenta_para_faltantes:
                    consumo_mee_agregado[cod_mee] = consumo_mee_agregado.get(cod_mee, 0) + cant_total
        else:
            # Camino B · clásico (1 presentación o sin presentaciones definidas)
            vol_ml = volumen_por_producto.get(producto_norm, 0)
            if vol_ml > 0 and cant_kg_total > 0:
                # Aproximación: 1g ≈ 1ml para productos cosméticos (densidad ~1)
                unidades_envasadas = int(round((cant_kg_total * 1000.0) / vol_ml))
            elif cant_kg_total > 0 and cuenta_para_faltantes and mee_por_producto.get(producto_norm):
                # Producto con envases configurados pero SIN volumen_ml registrado:
                # no se puede calcular cuántos envases necesita → su faltante de
                # MEE quedaría en CERO (sub-conteo silencioso). Lo reportamos para
                # que el usuario complete el volumen.
                productos_sin_volumen.add(producto or producto_norm)

            for me in mee_por_producto.get(producto_norm, []):
                if unidades_envasadas <= 0:
                    continue
                cant_total = unidades_envasadas * float(me['cantidad_por_unidad'] or 1)
                mees_nec.append({
                    'codigo': me['mee_codigo'],
                    'descripcion': me['descripcion'],
                    'tipo': me['tipo'],
                    'necesario_unidades': round(cant_total, 0),
                })
                cod_mee = (me['mee_codigo'] or '').strip().upper()
                if cod_mee and cuenta_para_faltantes:
                    consumo_mee_agregado[cod_mee] = consumo_mee_agregado.get(cod_mee, 0) + cant_total

        producciones_out.append({
            'id': pid,
            'producto': producto,
            'fecha': fecha,
            'lotes': lotes,
            'cantidad_kg': cant_kg_total,
            'mps_necesarias': mps_nec,
            'mees_necesarios': mees_nec,
            'unidades_envasadas_estimadas': unidades_envasadas,
            # Sebastian 5-may-2026: campos para vista calendario por sala
            'area_id': area_id,
            'area_codigo': area_codigo or '',
            'area_nombre': area_nombre or '',
            'estado': estado_norm,
            'inicio_real_at': inicio_real_at or None,
            'fin_real_at': fin_real_at or None,
            # Sebastián 8-may-2026: estado_display + flags rescate
            'estado_display': estado_display,
            'realizada': es_realizada,
            'en_proceso': es_en_proceso,
            'atrasada': es_atrasada,
            'inventario_descontado_at': desc_at or None,
            'es_clon_ignorado': es_clon,
        })

    # 10. Calcular faltantes agregados
    # Lo que YA está pedido NO se vuelve a pedir: OCs activas sin recibir +
    # SOLs pendientes sin OC. Sin esto el panel muestra como "faltante" lo
    # que Catalina ya compró → sobrecompra y SOLs duplicadas en cada recarga.
    # Clave en MAYÚSCULA · MP y MEE no comparten código.
    pedido_por_codigo = {}
    try:
        for r in c.execute("""
            SELECT UPPER(TRIM(i.codigo_mp)),
                   COALESCE(SUM(i.cantidad_g - COALESCE(i.cantidad_recibida_g,0)),0)
            FROM ordenes_compra_items i
            JOIN ordenes_compra oc ON oc.numero_oc = i.numero_oc
            WHERE (oc.estado IN ('Borrador','Pendiente','Revisada','Aprobada',
                                 'Autorizada','Parcial')
                   OR (oc.estado='Pagada' AND COALESCE(oc.fecha_recepcion,'')=''))
              AND COALESCE(TRIM(i.codigo_mp),'') != ''
            GROUP BY UPPER(TRIM(i.codigo_mp))
        """).fetchall():
            pedido_por_codigo[r[0]] = pedido_por_codigo.get(r[0], 0.0) + float(r[1] or 0)
    except sqlite3.OperationalError:
        pass
    try:
        for r in c.execute("""
            SELECT UPPER(TRIM(si.codigo_mp)), COALESCE(SUM(si.cantidad_g),0)
            FROM solicitudes_compra_items si
            JOIN solicitudes_compra s ON s.numero = si.numero
            WHERE s.estado IN ('Pendiente','En revision','Aprobada')
              AND COALESCE(s.numero_oc,'') = ''
              AND COALESCE(TRIM(si.codigo_mp),'') != ''
            GROUP BY UPPER(TRIM(si.codigo_mp))
        """).fetchall():
            pedido_por_codigo[r[0]] = pedido_por_codigo.get(r[0], 0.0) + float(r[1] or 0)
    except sqlite3.OperationalError:
        pass

    faltantes_mps = []
    for cod, g_total in consumo_mp_agregado.items():
        info = mp_info.get(cod, {'nombre': cod, 'proveedor': ''})
        # FIX 1-jun-2026 audit · lookup canónico 5-tier (antes solo id + nombre exacto
        # → MP con variante de nombre no bridgeada daba stock 0 → faltante FALSO →
        # sobre-compra · esto alimenta solicitar-faltantes-bulk que crea SOLs reales).
        s_actual = _lookup_stock_5tier(stock_mp, cod, info.get('nombre') or '')
        ya_pedido = pedido_por_codigo.get((cod or '').strip().upper(), 0.0)
        faltante = max(0.0, g_total - s_actual - ya_pedido)
        if faltante > 0:
            faltantes_mps.append({
                'codigo_mp': cod,
                'nombre': info['nombre'],
                'necesario_total_g': round(g_total, 2),
                'stock_actual_g': round(s_actual, 2),
                'ya_pedido_g': round(ya_pedido, 2),
                'faltante_g': round(faltante, 2),
                'proveedor_sugerido': info['proveedor'],
            })
    faltantes_mps.sort(key=lambda x: -x['faltante_g'])

    faltantes_mees = []
    for cod, u_total in consumo_mee_agregado.items():
        info = mee_info.get(cod, {'descripcion': cod, 'proveedor': ''})
        s_actual = float(stock_mee.get(cod, 0))
        ya_pedido = pedido_por_codigo.get((cod or '').strip().upper(), 0.0)
        faltante = max(0.0, u_total - s_actual - ya_pedido)
        if faltante > 0:
            faltantes_mees.append({
                'codigo': cod,
                'descripcion': info['descripcion'],
                'tipo': '',
                'necesario_total_u': round(u_total, 0),
                'stock_actual_u': round(s_actual, 0),
                'ya_pedido_u': round(ya_pedido, 0),
                'faltante_u': round(faltante, 0),
                'proveedor_sugerido': info['proveedor'],
            })
    faltantes_mees.sort(key=lambda x: -x['faltante_u'])

    # Proveedores únicos involucrados
    provs = {f['proveedor_sugerido'] for f in faltantes_mps if f['proveedor_sugerido']}
    provs |= {f['proveedor_sugerido'] for f in faltantes_mees if f['proveedor_sugerido']}

    # Sebastian 7-may-2026: agrupación por producto · una entry por producto
    # con TODAS sus fechas listadas, total kg, total lotes, MPs/MEEs faltantes
    # agregados. Soluciona el ruido visual de "lo mismo aparece en lunes y
    # miércoles" cuando son producciones duplicadas en `produccion_programada`.
    #
    # Detección de duplicados sospechosos: si dos producciones del MISMO
    # producto tienen exactamente mismos `lotes` y `cantidad_kg` y sus fechas
    # están dentro de 7 días, marcamos el grupo con `duplicado_sospechoso=True`
    # — Sebastián decide si limpiar via /api/programacion/limpiar-duplicados-producciones.
    grupos_por_producto = {}
    for p in producciones_out:
        key = (p.get('producto') or '').strip().upper()
        if not key:
            continue
        if key not in grupos_por_producto:
            grupos_por_producto[key] = {
                'producto': p.get('producto'),
                'fechas': [],          # lista de {fecha, pid, lotes, cantidad_kg, estado}
                'total_kg': 0.0,
                'total_lotes': 0,
                'mps_necesarias_set': {},   # codigo_mp -> {nombre, necesario_g}
                'mees_necesarios_set': {},  # codigo -> {descripcion, necesario_unidades}
                'unidades_envasadas_total': 0,
                'duplicado_sospechoso': False,
                'duplicados_detalle': [],  # entries que disparan la marca
            }
        g = grupos_por_producto[key]
        g['fechas'].append({
            'pid': p.get('id'),
            'fecha': p.get('fecha'),
            'lotes': p.get('lotes', 1),
            'cantidad_kg': p.get('cantidad_kg', 0),
            'estado': p.get('estado'),
            'area_nombre': p.get('area_nombre'),
            # Sebastián 8-may-2026: flags para que frontend distinga visualmente
            'estado_display': p.get('estado_display') or 'pendiente',
            'realizada': bool(p.get('realizada')),
            'en_proceso': bool(p.get('en_proceso')),
            'atrasada': bool(p.get('atrasada')),
            'inicio_real_at': p.get('inicio_real_at'),
            'fin_real_at': p.get('fin_real_at'),
            'inventario_descontado_at': p.get('inventario_descontado_at'),
        })
        # Solo sumar a totales lo que aún no se ha realizado · esos kg/lotes
        # representan trabajo PENDIENTE para Luis Enrique. Las realizadas se
        # ven como contexto pero no inflan la cifra "kg por hacer".
        if not p.get('realizada') and not p.get('en_proceso'):
            g['total_kg'] += float(p.get('cantidad_kg') or 0)
            g['total_lotes'] += int(p.get('lotes') or 0)
            g['unidades_envasadas_total'] += int(p.get('unidades_envasadas_estimadas') or 0)
        for m in (p.get('mps_necesarias') or []):
            cod = m.get('codigo_mp') or ''
            if not cod:
                continue
            existing = g['mps_necesarias_set'].get(cod)
            if existing:
                existing['necesario_g'] = (existing.get('necesario_g') or 0) + (m.get('necesario_g') or 0)
            else:
                g['mps_necesarias_set'][cod] = {
                    'codigo_mp': cod,
                    'nombre': m.get('nombre') or cod,
                    'necesario_g': m.get('necesario_g') or 0,
                }
        for me in (p.get('mees_necesarios') or []):
            cod = me.get('codigo') or ''
            if not cod:
                continue
            existing = g['mees_necesarios_set'].get(cod)
            if existing:
                existing['necesario_unidades'] = (existing.get('necesario_unidades') or 0) + (me.get('necesario_unidades') or 0)
            else:
                g['mees_necesarios_set'][cod] = {
                    'codigo': cod,
                    'descripcion': me.get('descripcion') or cod,
                    'tipo': me.get('tipo') or '',
                    'necesario_unidades': me.get('necesario_unidades') or 0,
                }

    # Detectar duplicados sospechosos · 2 producciones del mismo producto con
    # mismos lotes + cantidad_kg y fechas dentro de 7 días = casi seguro un
    # clon que quedó por sync mal hecho del calendar. Marcar grupo.
    from datetime import timedelta as _td, date as _date
    def _parse_iso(s):
        try:
            return _date.fromisoformat((s or '')[:10])
        except (ValueError, TypeError):
            return None
    for g in grupos_por_producto.values():
        # Sebastián 8-may-2026: solo comparar entre fechas NO-realizadas. Una
        # producción ya completada no es "clon" de la próxima programada — es
        # historia. Evita falsos positivos como "AZHC Lun 4 (realizada) clona
        # con AZHC Lun 11 (pendiente)".
        fs = [f for f in g['fechas']
              if not f.get('realizada') and not f.get('en_proceso')]
        if len(fs) <= 1:
            continue
        # Comparar pares
        for i in range(len(fs)):
            for j in range(i + 1, len(fs)):
                a, b = fs[i], fs[j]
                if (a.get('lotes') == b.get('lotes')
                        and abs(float(a.get('cantidad_kg') or 0)
                                - float(b.get('cantidad_kg') or 0)) < 0.01):
                    da, db = _parse_iso(a.get('fecha')), _parse_iso(b.get('fecha'))
                    if da and db and abs((da - db).days) <= 7:
                        g['duplicado_sospechoso'] = True
                        g['duplicados_detalle'].append({
                            'pid_a': a.get('pid'), 'fecha_a': a.get('fecha'),
                            'pid_b': b.get('pid'), 'fecha_b': b.get('fecha'),
                            'lotes': a.get('lotes'),
                            'cantidad_kg': a.get('cantidad_kg'),
                            'dias_separacion': abs((da - db).days),
                        })

    # Convertir sets a listas + ordenar
    producciones_agrupadas = []
    for g in grupos_por_producto.values():
        g['fechas'].sort(key=lambda x: x.get('fecha') or '')
        g['mps_necesarias'] = sorted(g.pop('mps_necesarias_set').values(),
                                      key=lambda m: m.get('nombre') or '')
        g['mees_necesarios'] = sorted(g.pop('mees_necesarios_set').values(),
                                       key=lambda m: m.get('descripcion') or '')
        # Faltantes agregados para este producto · join con sets globales
        mp_falt_set = {f['codigo_mp']: f for f in faltantes_mps}
        mee_falt_set = {f['codigo']: f for f in faltantes_mees}
        g['faltantes_mps_count'] = sum(1 for m in g['mps_necesarias']
                                        if m['codigo_mp'] in mp_falt_set)
        g['faltantes_mees_count'] = sum(1 for m in g['mees_necesarios']
                                         if m['codigo'] in mee_falt_set)
        producciones_agrupadas.append(g)
    # Orden: con duplicados sospechosos primero, luego por nombre
    producciones_agrupadas.sort(key=lambda x: (
        not x['duplicado_sospechoso'],
        x['producto'] or '',
    ))

    # Sebastián 8-may-2026: contadores por estado para el resumen del panel
    n_realizadas = sum(1 for p in producciones_out if p.get('realizada'))
    n_en_proceso = sum(1 for p in producciones_out if p.get('en_proceso'))
    n_atrasadas = sum(1 for p in producciones_out if p.get('atrasada'))
    n_pendientes = sum(1 for p in producciones_out
                       if not p.get('realizada') and not p.get('en_proceso')
                       and not p.get('atrasada'))

    # Sebastián 9-may-2026: contar atrasadas pendientes OCULTAS (anteriores
    # a atrasadas_cutoff) para mostrar en el toggle "Mostrar atrasadas viejas (N)".
    # Una atrasada-pendiente vieja es: estado != cancelado, sin inicio_real_at,
    # sin desc_at, fecha < atrasadas_cutoff.
    # NO se aplica past_window aquí · una basura de hace 30d sigue siendo
    # ruido oculto que el user puede querer ver/limpiar.
    n_atrasadas_ocultas = 0
    try:
        row = c.execute("""
            SELECT COUNT(*) FROM produccion_programada
            WHERE LOWER(COALESCE(estado, '')) != 'cancelado'
              AND COALESCE(inicio_real_at, '') = ''
              AND COALESCE(inventario_descontado_at, '') = ''
              AND fecha_programada < ?
        """, (atrasadas_cutoff,)).fetchone()
        n_atrasadas_ocultas = int(row[0] or 0) if row else 0
    except Exception:
        pass

    return jsonify({
        'horizonte_dias': dias,
        'pasado_dias': pasado_dias,
        'atrasadas_max_dias': atrasadas_max_dias,
        'producciones': producciones_out,
        'producciones_agrupadas': producciones_agrupadas,
        'faltantes_mps': faltantes_mps,
        'faltantes_mees': faltantes_mees,
        'productos_sin_volumen': sorted(productos_sin_volumen),
        'resumen': {
            'n_producciones': len(producciones_out),
            'n_productos_unicos': len(producciones_agrupadas),
            'n_productos_con_duplicados': sum(1 for g in producciones_agrupadas
                                                if g['duplicado_sospechoso']),
            'n_mps_faltantes': len(faltantes_mps),
            'n_mees_faltantes': len(faltantes_mees),
            'n_productos_sin_volumen': len(productos_sin_volumen),
            'n_proveedores_unicos': len(provs),
            'n_realizadas': n_realizadas,
            'n_en_proceso': n_en_proceso,
            'n_atrasadas': n_atrasadas,
            'n_pendientes': n_pendientes,
            'n_atrasadas_ocultas': n_atrasadas_ocultas,
        },
    })


@bp.route('/api/programacion/limpiar-duplicados-producciones', methods=['POST'])
def limpiar_duplicados_producciones():
    """Detecta y elimina producciones duplicadas en `produccion_programada`.

    Sebastián 7-may-2026 (Luis Enrique): el calendario mostraba la misma
    producción en lunes y miércoles porque algún sync dejó clones en la
    tabla. Este endpoint detecta pares con mismo producto + lotes +
    cantidad_kg dentro de 7 días, conserva la fecha más temprana y borra
    las posteriores.

    No toca:
      · Producciones ya descontadas (`inventario_descontado_at` IS NOT NULL)
      · Producciones canceladas/completadas
      · Producciones con `inicio_real_at` (ya empezó · es real, no clon)

    Body:
      {dry_run: bool, horizonte_dias: int}  (default dry_run=True, horizonte=30)

    Returns:
      200 {ok, dry_run, grupos_detectados, producciones_borradas,
           plan: [{producto, fechas: [{pid, fecha}]}], mensaje}
    """
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    user = session.get('compras_user', '')
    # Solo COMPRAS+ADMIN+jefe de producción pueden limpiar
    permitidos = set(COMPRAS_USERS) | set(ADMIN_USERS)
    if user not in permitidos:
        return jsonify({'error': 'Solo Compras/Admin/Jefe Producción pueden limpiar'}), 403

    body = request.get_json(silent=True) or {}
    dry_run = bool(body.get('dry_run', True))
    try:
        horizonte = max(7, min(int(body.get('horizonte_dias', 30)), 365))
    except (ValueError, TypeError):
        horizonte = 30

    conn = get_db(); c = conn.cursor()
    fecha_hoy = datetime.now().strftime('%Y-%m-%d')
    fecha_cutoff = (datetime.now() + timedelta(days=horizonte)).strftime('%Y-%m-%d')

    # Cargar candidatos · producciones que NO están descontadas, ni canceladas/
    # completadas, ni ya empezadas, en el horizonte.
    # Sebastián 19-may-2026 · FIX hueco principio Fijo vs Sugerido:
    # excluir 'eos_plan' / 'eos_b2b' / 'eos_retroactivo'. Antes este endpoint
    # podía borrar Fijos (lo que Alejandro arrastró/editó o pedidos B2B)
    # si por azar coincidían producto+lotes+kg con una canónica cercana.
    rows = c.execute("""
        SELECT id, producto, fecha_programada,
               COALESCE(lotes, 1), COALESCE(cantidad_kg, 0),
               COALESCE(LOWER(estado), 'pendiente') as estado_norm,
               COALESCE(inicio_real_at, '') as inicio,
               COALESCE(inventario_descontado_at, '') as desc_at
        FROM produccion_programada
        WHERE COALESCE(inventario_descontado_at, '') = ''
          AND LOWER(COALESCE(estado, '')) NOT IN ('cancelado', 'completado')
          AND COALESCE(inicio_real_at, '') = ''
          AND COALESCE(origen, '') NOT IN ('eos_plan', 'eos_b2b', 'eos_retroactivo')
          AND fecha_programada >= ?
          AND fecha_programada <= ?
        ORDER BY producto, fecha_programada ASC
    """, (fecha_hoy, fecha_cutoff)).fetchall()

    # Agrupar por (producto_norm, lotes, cantidad_kg) y buscar pares dentro de 7d
    from datetime import date as _date
    def _iso(s):
        try:
            return _date.fromisoformat((s or '')[:10])
        except (ValueError, TypeError):
            return None

    grupos = {}
    for r in rows:
        pid, producto, fecha, lotes, cant_kg, _est, _ini, _desc = r
        key = ((producto or '').strip().upper(), int(lotes or 1),
               round(float(cant_kg or 0), 2))
        grupos.setdefault(key, []).append({'pid': pid, 'fecha': fecha,
                                            'producto': producto})

    # Para cada grupo con >1 entries, encontrar clusters de fechas <=7d apart
    a_borrar = []  # [{pid, producto, fecha}]
    plan = []      # [{producto, fechas: [{pid, fecha, accion}]}]
    for (prod_norm, lotes, cant), entries in grupos.items():
        if len(entries) < 2:
            continue
        # Ordenar por fecha
        entries.sort(key=lambda e: e.get('fecha') or '')
        # Tomar la primera como "ancla" · borrar las demás SI están dentro de
        # 7 días de la ancla
        ancla = entries[0]
        ancla_d = _iso(ancla['fecha'])
        if not ancla_d:
            continue
        clones = []
        for e in entries[1:]:
            ed = _iso(e.get('fecha'))
            if ed and abs((ed - ancla_d).days) <= 7:
                clones.append(e)
        if not clones:
            continue
        plan.append({
            'producto': ancla['producto'],
            'lotes': lotes, 'cantidad_kg': cant,
            'fechas': (
                [{'pid': ancla['pid'], 'fecha': ancla['fecha'],
                  'accion': 'KEEP (más temprana)'}]
                + [{'pid': cl['pid'], 'fecha': cl['fecha'], 'accion': 'BORRAR'}
                   for cl in clones]
            ),
        })
        for cl in clones:
            a_borrar.append({'pid': cl['pid'], 'producto': ancla['producto'],
                              'fecha': cl.get('fecha')})

    if dry_run:
        return jsonify({
            'ok': True,
            'dry_run': True,
            'grupos_detectados': len(plan),
            'producciones_a_borrar': len(a_borrar),
            'plan': plan,
            'mensaje': (f'Detectados {len(plan)} grupos con duplicados · '
                        f'{len(a_borrar)} producciones se borrarían'),
        }), 200

    if not a_borrar:
        return jsonify({
            'ok': True, 'dry_run': False,
            'grupos_detectados': 0, 'producciones_borradas': 0,
            'plan': [], 'mensaje': 'No hay duplicados que limpiar',
        }), 200

    try:
        pids = [b['pid'] for b in a_borrar]
        ph = ','.join(['?'] * len(pids))
        # Sebastián 19-may-2026 · FIX: era DELETE duro que dejaba la
        # producción sin rastro. Ahora soft-cancel con marca en observaciones
        # y mantiene el row para auditoría / recuperación. Defensa en
        # profundidad: el WHERE TAMBIÉN excluye orígenes Fijos por si el
        # SELECT cambiara en el futuro (cinturón + tirantes).
        c.execute(
            f"""UPDATE produccion_programada
                SET estado = 'cancelado',
                    observaciones = COALESCE(observaciones, '')
                      || ' · CANCELADO_LIMPIAR_DUPLICADOS_'
                      || datetime('now', '-5 hours')
                WHERE id IN ({ph})
                  AND COALESCE(origen, '') NOT IN ('eos_plan', 'eos_b2b', 'eos_retroactivo')""",
            pids,
        )
        canceladas = c.rowcount or 0
        try:
            audit_log(
                c, usuario=user,
                accion='LIMPIAR_DUPLICADOS_PRODUCCIONES',
                tabla='produccion_programada',
                registro_id='bulk',
                antes={'ids': pids},
                despues={'grupos': len(plan), 'canceladas': canceladas,
                          'horizonte_dias': horizonte},
                detalle=(f"Soft-canceló {canceladas} producciones duplicadas en "
                          f"{len(plan)} grupos · horizonte {horizonte}d · "
                          f"excluyó eos_plan/eos_b2b/eos_retroactivo"),
            )
        except Exception as e:
            log.warning('audit_log LIMPIAR_DUPLICADOS_PRODUCCIONES falló: %s', e)
        conn.commit()
    except Exception as e:
        try:
            conn.rollback()
        except Exception:
            pass
        log.exception('limpiar_duplicados_producciones falló: %s', e)
        return jsonify({'error': str(e)}), 500

    return jsonify({
        'ok': True, 'dry_run': False,
        'grupos_detectados': len(plan),
        # mantener clave `producciones_borradas` para compat con frontend existente
        'producciones_borradas': canceladas,
        'producciones_canceladas': canceladas,
        'plan': plan,
        'mensaje': (f'✓ Canceladas {canceladas} producciones duplicadas en '
                     f'{len(plan)} grupos · horizonte {horizonte}d · '
                     f'lo Fijo NO se tocó'),
    }), 200


@bp.route('/api/programacion/serigrafia-cola', methods=['GET'])
def serigrafia_cola():
    """Cola de envases por produccion (Planta · Sebastian 29-jun): por cada produccion futura no-iniciada,
    EN ORDEN DE FECHA, el envase y la cantidad teorica de envases que va a gastar (unidades = kg*1000/ml,
    repartido por presentacion via _composicion_envases_lote). Base para la logistica de serigrafia
    (enviar los envases a serigrafia con tiempo antes de la produccion)."""
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    conn = get_db()
    c = conn.cursor()
    try:
        rows = c.execute(
            "SELECT id, producto, fecha_programada, COALESCE(cantidad_kg,0) FROM produccion_programada "
            "WHERE LOWER(COALESCE(estado,'')) NOT IN ('cancelado','completado') "
            "AND COALESCE(inicio_real_at,'')='' AND COALESCE(fin_real_at,'')='' "
            "AND COALESCE(fecha_programada,'') >= date('now','-5 hours') "
            "AND COALESCE(fecha_programada,'') <= date('now','-5 hours','+180 days') "
            "ORDER BY fecha_programada, producto").fetchall()
    except Exception as e:
        return jsonify({'error': str(e)[:200], 'items': []}), 500
    # marcación por envase (mig 312) · tipo (serigrafia/tampografia/pre_impreso) + proveedor · pre_impreso NO entra
    _marc = {}
    try:
        for (mc, mt, mp) in c.execute("SELECT codigo, COALESCE(marcacion_tipo,''), COALESCE(marcacion_proveedor,'') FROM maestro_mee").fetchall():
            _marc[(mc or '').strip().upper()] = (mt or '', mp or '')
    except Exception:
        _marc = {}
    # stock canónico (M26/M57): _get_mee_stock excluye CUARENTENA/RECHAZADO + case-insensitive + Ajuste.
    try:
        _stock = _get_mee_stock(conn)
    except Exception:
        _stock = {}
    # De que envase LIMPIO sale cada impreso/serigrafiado (el puente de Fase 0). Sin el, cuando
    # el impreso no alcance se puede avisar igual, pero no se puede decir QUE mandar a marcar --
    # y entonces se declara, no se supone (M100).
    _base_de, _desc_mee = {}, {}
    try:
        for (mc, dd) in c.execute(
                "SELECT UPPER(TRIM(codigo)), COALESCE(descripcion,'') FROM maestro_mee").fetchall():
            _desc_mee[mc] = dd
    except Exception:
        _desc_mee = {}
    try:
        for (mc, mr) in c.execute(
                "SELECT UPPER(TRIM(codigo)), UPPER(TRIM(COALESCE(material_referencia,''))) "
                "  FROM maestro_mee WHERE COALESCE(material_referencia,'')<>''").fetchall():
            _base_de[mc] = mr
    except Exception:
        _base_de = {}

    from datetime import datetime as _dtSC, timedelta as _tdSC
    # Lo que se lleva consumido de cada envase a lo largo de la cola. Las producciones vienen EN
    # ORDEN DE FECHA, que es como se gasta de verdad: el stock es uno solo y lo que se lleva la
    # produccion de septiembre ya no esta para la de octubre.
    _consumido = {}
    out = []
    for (lid, prod, fecha, kg) in rows:
        try:
            comp = _composicion_envases_lote(c, lid)
        except Exception:
            comp = None
        if not comp or not comp.get('variantes'):
            continue
        for v in (comp.get('variantes') or []):
            env = (v.get('envase_codigo') or '').strip()
            uds = int(round(float(v.get('unidades_estimadas') or 0)))
            if not env or uds <= 0:
                continue
            _mt, _mp = _marc.get(env.upper(), ('', ''))
            _envu = env.upper()
            _antes = _consumido.get(_envu, 0)
            _consumido[_envu] = _antes + uds
            if _mt == 'pre_impreso':
                # Sebastian (9-ago): *"todo lo impreso va primero; cuando no alcanza, entonces
                # debe decir se debe enviar tal envase a serigrafia o solicitar etiqueta"*.
                #
                # Antes esta rama hacia `continue` a secas: mientras el impreso alcanzara todo
                # bien, y **el dia que no alcanzara nadie se enteraba**. El impreso no se manda a
                # marcar (ya viene marcado), pero eso no es lo mismo que no mirarlo.
                _hay = float(_stock.get(_envu, 0) or 0)
                _falta = int(round(max(0.0, (_antes + uds) - _hay) - max(0.0, _antes - _hay)))
                if _falta <= 0:
                    continue                  # el impreso alcanza · no hay nada que hacer
                _limpio = _base_de.get(_envu, '')
                _etq = (v.get('etiqueta_codigo') or v.get('etiqueta') or '').strip()
                try:
                    _fe = (_dtSC.fromisoformat(str(fecha)[:10]) - _tdSC(days=15)).date().isoformat()
                except Exception:
                    _fe = ''
                # ⚠ La fila es una ORDEN DE TRABAJO: la pantalla de Compras la usa para mandar a
                # marcar. Entonces tiene que traer el envase que hay que MANDAR (el limpio, no el
                # impreso, que ya viene marcado) y la cantidad que FALTA, no la de la producción
                # entera. Emitirla con el impreso y el total haría que Catalina mande el frasco
                # equivocado, por la cantidad equivocada -- y la pantalla no tendría cómo saberlo.
                _mt_lim, _mp_lim = _marc.get(_limpio, ('', '')) if _limpio else ('', '')
                # ⚠ Si NO hay envase limpio anclado, la fila NO lleva el codigo del impreso: ese
                # frasco YA viene serigrafiado y mandarlo a marcar es pagar por marcar algo que ya
                # esta marcado. Queda vacio y el aviso dice que falta el ancla -- un hueco DICHO
                # es accionable; uno rellenado con lo que habia a mano produce una orden mal.
                out.append({
                    'produccion_id': lid, 'producto': prod, 'fecha': fecha, 'fecha_envio': _fe,
                    'envase_codigo': _limpio,
                    'envase_desc': (_desc_mee.get(_limpio, '') if _limpio
                                    else 'falta anclar el envase limpio de ' + str(env)),
                    'etiqueta': v.get('etiqueta', ''), 'volumen_ml': v.get('volumen_ml', 0),
                    'unidades': _falta, 'kg': float(kg or 0),
                    'marcacion_tipo': (_mt_lim or ('etiqueta' if (not _limpio and _etq) else '')),
                    'marcacion_proveedor': _mp_lim,
                    'stock_envase': float(_stock.get(_limpio, 0) or 0) if _limpio else _hay,
                    'envase_impreso': env,
                    'stock_impreso': _hay,
                    'unidades_produccion': uds,
                    # Lo que hace accionable la fila: cuantos faltan y las dos salidas posibles.
                    'impreso_no_alcanza': True,
                    'faltan': _falta,
                    'envase_limpio': _limpio,
                    'etiqueta_codigo': _etq,
                    'accion': ('enviar_a_serigrafiar' if _limpio else
                               ('solicitar_etiqueta' if _etq else 'sin_salida_definida')),
                    'aviso': (('El impreso no alcanza para esta produccion: faltan %d. '
                               'Enviar %s a marcar antes del %s') % (_falta, _limpio, _fe or 's/f')
                              if _limpio else
                              (('El impreso no alcanza: faltan %d. No hay envase limpio anclado a '
                                '%s (material_referencia), asi que no se puede decir que mandar a '
                                'marcar; se puede solicitar la etiqueta %s') % (_falta, env, _etq))
                              if _etq else
                              ('El impreso no alcanza: faltan %d, y este envase no tiene ni '
                               'envase limpio anclado ni etiqueta definida' % _falta)),
                })
                continue
            _fenv = ''
            try:
                _fenv = (_dtSC.fromisoformat(str(fecha)[:10]) - _tdSC(days=15)).date().isoformat()
            except Exception:
                _fenv = ''
            out.append({
                'produccion_id': lid, 'producto': prod, 'fecha': fecha, 'fecha_envio': _fenv,
                'envase_codigo': env, 'envase_desc': v.get('envase_descripcion', ''),
                'etiqueta': v.get('etiqueta', ''), 'volumen_ml': v.get('volumen_ml', 0),
                'unidades': uds, 'kg': float(kg or 0),
                'marcacion_tipo': _mt, 'marcacion_proveedor': _mp,
                'stock_envase': _stock.get(env.upper(), 0),
            })
    return jsonify({'items': out, 'total': len(out)})


@bp.route('/api/programacion/marcacion-orden/enviar', methods=['POST'])
def marcacion_orden_enviar():
    """Fase B · Enviar envases a marcar: Salida del BASE en el kardex + crea la orden (estado=enviado).
    El base = material_referencia del serigrafiado (Fase 0) o el mismo envase si no hay referencia."""
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    user = session.get('compras_user', '')
    d = request.json or {}
    serig = (d.get('serigrafiado_codigo') or d.get('envase_codigo') or '').strip()
    try:
        cantidad = float(d.get('cantidad') or 0)
    except (TypeError, ValueError):
        cantidad = 0
    metodo = (d.get('metodo') or '').strip()
    proveedor = (d.get('proveedor') or '').strip()
    producto = (d.get('producto') or '').strip()
    prod_id = d.get('produccion_id')
    fecha_alistar = (d.get('fecha_alistar') or '').strip()
    hora_alistar = (d.get('hora_alistar') or '').strip()
    urgencia_m = (d.get('urgencia') or 'media').strip()
    if not serig or cantidad <= 0:
        return jsonify({'error': 'serigrafiado_codigo y cantidad (>0) requeridos'}), 400
    from datetime import datetime as _dtM, timedelta as _tdM
    _hoy = (_dtM.utcnow() - _tdM(hours=5)).date().isoformat()
    conn = get_db()
    c = conn.cursor()
    if not c.execute("SELECT 1 FROM maestro_mee WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))", (serig,)).fetchone():
        return jsonify({'error': f'envase {serig} no existe'}), 400
    # Gate DT de arte/etiqueta (Sebastián 19-jul): un envase NO se envía a serigrafía/tampografía
    # sin que Dirección Técnica haya aprobado el arte del producto. Toggle en app_settings
    # 'artes_gate_dt' (default OFF · M39/M68 · se prende cuando el Drive de artes esté cargado).
    # Override admin con forzar=true (auditado).
    try:
        _gate_on = False
        _g = c.execute("SELECT valor FROM app_settings WHERE clave='artes_gate_dt' LIMIT 1").fetchone()
        if _g and str(_g[0]).strip() in ('1', 'true', 'True', 'on'):
            _gate_on = True
        if _gate_on and producto and not (d.get('forzar') and user in ADMIN_USERS):
            from blueprints.artes import arte_aprobado_para
            if not arte_aprobado_para(conn, producto):
                return jsonify({'error': 'ARTE_DT_NO_APROBADO',
                                'detalle': f'El arte/etiqueta de "{producto}" no está aprobado por Dirección Técnica. '
                                           'Solicita la revisión en /artes antes de enviar a marcación.'}), 409
    except Exception:
        pass  # gate OFF por defecto · un fallo del check nunca bloquea la marcación (fail-open)
    base = serig
    try:
        r = c.execute("SELECT COALESCE(material_referencia,'') FROM maestro_mee WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))", (serig,)).fetchone()
        if r and (r[0] or '').strip():
            base = r[0].strip()
    except Exception:
        pass
    # Gate de stock del base ANTES de la Salida (revisor adversarial 19-jul · BUG-1): sin esto, enviar más de
    # lo que hay dejaba SUM(movimientos_mee) NEGATIVO, enmascarado como 0 por _get_mee_stock (M5/M6). Override
    # con forzar=true. El stock es el canónico (SUM), no el cache.
    _stock_base = 0.0
    try:
        _stock_base = float(_get_mee_stock(conn).get(base.strip().upper(), 0) or 0)
    except Exception:
        _stock_base = 0.0
    if not d.get('forzar') and cantidad > _stock_base + 0.01:
        return jsonify({'error': 'Stock insuficiente del base ' + base + ': hay ' + ('%g' % _stock_base) +
                        ', se quieren enviar ' + ('%g' % cantidad) + '. Recibí/ajustá el envase o reenviá con forzar=true.',
                        'codigo': 'STOCK_INSUFICIENTE', 'stock': _stock_base}), 422
    # ⚠ ANTI-DOBLE (Catalina 4-ago · "descuenta doble"): "Solicitar alistamiento" llama a ESTE
    # mismo endpoint, y hasta ahora insertaba la orden sin mirar si ya habia una abierta. Dos
    # clics = dos ordenes = dos Salidas del base. El CAS protege TRANSICIONES, no la CREACION
    # (M63): lo que hace falta es el guard.
    # Un reenvio legitimo existe (mandar otra tanda del mismo envase), asi que NO se prohibe:
    # se avisa con lo que ya hay y se pasa con `forzar_marcacion`.
    # ⚠ FLAG PROPIO (4-ago · revisión adversarial): este guard NO puede reusar `forzar`, porque
    # ese flag ya apaga el guard de STOCK_INSUFICIENTE (el que evita kardex negativo) y el gate
    # de arte de Dirección Técnica. Si la UI reenviara con `forzar` para confirmar una segunda
    # tanda legítima, de paso apagaría los otros dos sin que nadie lo haya pedido. Un flag por
    # control. `forzar` se sigue aceptando para no romper a un caller viejo.
    if not (d.get('forzar_marcacion') or d.get('forzar')):
        try:
            _ya = c.execute(
                "SELECT id, cantidad_enviada, fecha_envio FROM marcacion_ordenes "
                " WHERE UPPER(TRIM(base_codigo))=UPPER(TRIM(?)) "
                "   AND UPPER(TRIM(serigrafiado_codigo))=UPPER(TRIM(?)) "
                "   AND LOWER(COALESCE(estado,''))='enviado' "
                "   AND ((produccion_id IS NULL AND ? IS NULL) OR produccion_id=?) "
                " ORDER BY id DESC LIMIT 1",
                (base, serig, prod_id, prod_id)).fetchone()
        except Exception as _e:
            log.warning('no pude revisar ordenes de marcacion abiertas: %s', _e)
            _ya = None
        if _ya:
            return jsonify({
                'error': 'Ese envase YA está en marcación para esta producción · si mandás otra '
                         'tanda, confirmá para no descontarlo dos veces',
                'codigo': 'MARCACION_YA_ABIERTA',
                'orden_id': _ya[0], 'cantidad_enviada': _ya[1], 'fecha_envio': _ya[2],
                # El flag a reenviar es SÓLO el de este guard: `forzar` apaga además el de
                # stock y el gate de arte, y confirmar una segunda tanda no puede apagar eso.
                'puede_forzar': True, 'flag': 'forzar_marcacion'}), 409

    # Salida del base (sale a marcar)
    try:
        c.execute("INSERT INTO movimientos_mee (mee_codigo, tipo, cantidad, unidad, lote_ref, responsable, observaciones) "
                  "VALUES (?, 'Salida', ?, 'und', 'MARCACION', ?, ?)",
                  (base, cantidad, user, ('Enviado a ' + (metodo or 'marcar') + (' (' + proveedor + ')' if proveedor else ''))))
    except Exception as e:
        return jsonify({'error': 'No se pudo registrar la salida: ' + str(e)[:150]}), 500
    # Decrementar el cache stock_actual del base (simetría con la recepción · revisor BUG-2 · CASE anti-negativo M51)
    try:
        c.execute("UPDATE maestro_mee SET stock_actual = CASE WHEN COALESCE(stock_actual,0) - ? < 0 THEN 0 "
                  "ELSE COALESCE(stock_actual,0) - ? END WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))",
                  (cantidad, cantidad, base))
    except Exception:
        pass
    c.execute("INSERT INTO marcacion_ordenes (base_codigo, serigrafiado_codigo, producto_nombre, metodo, proveedor, "
              "cantidad_enviada, produccion_id, fecha_envio, fecha_alistar, hora_alistar, urgencia, estado, creado_por, creado_en) "
              "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'enviado', ?, ?)",
              (base, serig, producto, metodo, proveedor, cantidad, prod_id, _hoy, fecha_alistar, hora_alistar, urgencia_m, user, _hoy))
    oid = c.lastrowid
    try:
        from audit_helpers import audit_log as _al
        _al(c, usuario=user, accion='MARCACION_ENVIAR', tabla='marcacion_ordenes', registro_id=oid,
            despues={'base': base, 'serigrafiado': serig, 'cantidad': cantidad})
    except Exception:
        pass
    conn.commit()
    return jsonify({'ok': True, 'orden_id': oid, 'base': base, 'serigrafiado': serig})


def _marcacion_liberar_core(c, oid, user, rol, chk):
    """Núcleo de liberación del retorno de marcación (Fase 2+3). Saca de CUARENTENA→VIGENTE,
    califica serigrafiado + proveedor, registra el checklist de arte. Devuelve (ok, error, code)."""
    from datetime import datetime as _dtM, timedelta as _tdM
    _hoy = (_dtM.utcnow() - _tdM(hours=5)).date().isoformat()
    o = c.execute("SELECT serigrafiado_codigo, COALESCE(proveedor,''), COALESCE(estado,'') FROM marcacion_ordenes WHERE id=?", (oid,)).fetchone()
    if not o:
        return (False, 'Orden no existe', 404)
    if o[2] != 'recibido':
        return (False, f'Orden en estado {o[2]} · debe estar recibida para liberar', 409)
    serig, prov = o[0], o[1]
    # CAS: reclamar la liberacion + registrar checklist
    c.execute("UPDATE marcacion_ordenes SET estado='liberado', liberado_at=?, liberado_por=?, chk_rol=?, "
              "chk_arte=?, chk_estado=?, chk_caracteristicas=?, chk_cantidad=?, chk_observaciones=? "
              "WHERE id=? AND COALESCE(estado,'')='recibido'",
              (_hoy, user, rol, int(bool(chk.get('arte'))), int(bool(chk.get('estado'))),
               int(bool(chk.get('caracteristicas'))), int(bool(chk.get('cantidad'))),
               (chk.get('observaciones') or '')[:500], oid))
    if (c.rowcount or 0) == 0:
        return (False, 'Orden ya liberada por otro', 409)
    # 1) sacar de cuarentena (VIGENTE) la entrada de ESTA orden
    try:
        c.execute("UPDATE movimientos_mee SET estado='VIGENTE' WHERE UPPER(TRIM(mee_codigo))=UPPER(TRIM(?)) "
                  "AND lote_ref='MARCACION-RET' AND COALESCE(estado,'')='CUARENTENA' AND COALESCE(observaciones,'') LIKE ?",
                  (serig, '%orden ' + str(oid) + ' %'))
    except Exception:
        pass
    # 1b) ⚠ SINCRONIZAR EL CACHE (4-ago · revisión adversarial). `aplicar_movimiento_mee`
    # CLAMPEA toda Salida contra `maestro_mee.stock_actual`, no contra la suma del kardex. El
    # envío a marcar DECREMENTA ese cache para el base, pero el retorno insertaba la Entrada del
    # serigrafiado sin volver a subirlo nunca: con el cache en 0, el descuento de envasado
    # registraba una Salida de **CERO** -- sin error, sin log, y con el ítem marcado como
    # consumido. O sea que el doble descuento se había vuelto CERO descuento, que es peor: el
    # kardex dice que el envase sigue en bodega.
    # Va acá y no en `recibir` porque hasta la liberación el material está en CUARENTENA, y el
    # stock canónico excluye la cuarentena: subir el cache antes lo dejaría discrepando.
    try:
        _ent = c.execute(
            "SELECT COALESCE(SUM(cantidad),0) FROM movimientos_mee "
            " WHERE UPPER(TRIM(mee_codigo))=UPPER(TRIM(?)) AND lote_ref='MARCACION-RET' "
            "   AND COALESCE(observaciones,'') LIKE ?",
            (serig, '%orden ' + str(oid) + ' %')).fetchone()
        _cant_lib = float((_ent[0] if _ent else 0) or 0)
        if _cant_lib > 0:
            c.execute("UPDATE maestro_mee SET stock_actual = COALESCE(stock_actual,0) + ? "
                      " WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))", (_cant_lib, serig))
    except Exception as _ec:
        # No se traga: si el cache no se sincroniza, el próximo descuento sale en cero (M4).
        log.warning('marcacion: no pude sincronizar el cache de %s (orden %s): %s',
                    serig, oid, _ec)

    # 2) calificar el envase serigrafiado (material calificado)
    try:
        c.execute("UPDATE maestro_mee SET calificado=1, calificado_at=?, calificado_por=? WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))",
                  (_hoy, user, serig))
    except Exception:
        pass
    # 3) auto-calificar el proveedor (recepcion conforme · auditable)
    if prov:
        try:
            c.execute("SAVEPOINT sp_marc_cal")
            ex = c.execute("SELECT 1 FROM proveedores_calificacion WHERE LOWER(TRIM(proveedor))=LOWER(TRIM(?))", (prov,)).fetchone()
            if ex:
                c.execute("UPDATE proveedores_calificacion SET estado='aprobado', fecha_aprobacion=?, evaluado_por=? "
                          "WHERE LOWER(TRIM(proveedor))=LOWER(TRIM(?))", (_hoy, user, prov))
            else:
                c.execute("INSERT INTO proveedores_calificacion (proveedor, estado, categoria, fecha_aprobacion, evaluado_por, observaciones, creado_por, creado_en) "
                          "VALUES (?, 'aprobado', 'Envases/Marcacion', ?, ?, 'Auto - recepcion conforme de marcacion', ?, ?)",
                          (prov, _hoy, user, user, _hoy))
            c.execute("RELEASE SAVEPOINT sp_marc_cal")
        except Exception:
            try:
                c.execute("ROLLBACK TO SAVEPOINT sp_marc_cal")
            except Exception:
                pass
    try:
        from audit_helpers import audit_log as _al
        _al(c, usuario=user, accion='MARCACION_LIBERAR_CHECKLIST', tabla='marcacion_ordenes', registro_id=oid,
            despues={'serigrafiado': serig, 'proveedor': prov, 'rol': rol, 'checklist': chk})
    except Exception:
        pass
    return (True, None, 200)


@bp.route('/api/programacion/marcacion-orden/<int:oid>/liberar', methods=['POST'])
def marcacion_orden_liberar(oid):
    """DEPRECADO (Fase 2 · Sebastián 21-jul): la liberación directa por Compras SIN control se cerró.
    El retorno de marcación se libera SOLO por el checklist de arte (DT/Aseguramiento/Calidad)."""
    return jsonify({'error': 'Liberación directa deshabilitada · usá el checklist de arte (DT/Aseguramiento/Calidad)',
                    'codigo': 'USAR_CHECKLIST'}), 409


@bp.route('/api/programacion/marcacion-orden/<int:oid>/liberar-checklist', methods=['POST'])
def marcacion_orden_liberar_checklist(oid):
    """Fase 2+3 (Sebastián 21-jul): libera el retorno de marcación tras el CHECKLIST ligero de arte
    (arte / estado / características / cantidad). Solo Dirección Técnica, Aseguramiento o Calidad
    (registro electrónico: quién + rol + checks + observaciones + audit). El envase ya es conocido
    y ya pasó calidad; lo nuevo es la impresión."""
    from config import TECNICA_USERS, CALIDAD_USERS, ADMIN_USERS
    u = session.get('compras_user', '')
    if not u:
        return jsonify({'error': 'No autorizado'}), 401
    _u = u.lower()
    if _u in {x.lower() for x in ADMIN_USERS}:
        rol = 'Admin'
    elif _u in {x.lower() for x in TECNICA_USERS}:
        rol = 'Dirección Técnica'
    elif _u in {x.lower() for x in CALIDAD_USERS}:
        rol = 'Calidad'
    else:
        return jsonify({'error': 'Solo Dirección Técnica o Calidad pueden liberar el checklist de arte'}), 403
    d = request.json or {}
    chk = {'arte': bool(d.get('arte')), 'estado': bool(d.get('estado')),
           'caracteristicas': bool(d.get('caracteristicas')), 'cantidad': bool(d.get('cantidad')),
           'observaciones': (d.get('observaciones') or '').strip()}
    if not (chk['arte'] and chk['estado'] and chk['caracteristicas']):
        return jsonify({'error': 'Para liberar, arte + estado + características deben estar conformes. Si algo no cumple, no liberes y dejá la observación.',
                        'codigo': 'CHECKLIST_INCOMPLETO'}), 400
    conn = get_db(); c = conn.cursor()
    ok, err, code = _marcacion_liberar_core(c, oid, u, rol, chk)
    if not ok:
        conn.rollback()
        return jsonify({'error': err}), code
    conn.commit()
    return jsonify({'ok': True, 'orden_id': oid, 'rol': rol})


@bp.route('/api/programacion/marcacion-orden/<int:oid>/recibir', methods=['POST'])
def marcacion_orden_recibir(oid):
    """Fase B · Recibir el retorno de marcacion: Entrada del SERIGRAFIADO en CUARENTENA (Calidad libera con el
    flujo MEE existente). CAS: reclama la orden (estado=enviado) antes de insertar (anti-doble-recepcion)."""
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    user = session.get('compras_user', '')
    d = request.json or {}
    from datetime import datetime as _dtM, timedelta as _tdM
    _hoy = (_dtM.utcnow() - _tdM(hours=5)).date().isoformat()
    conn = get_db()
    c = conn.cursor()
    o = c.execute("SELECT serigrafiado_codigo, cantidad_enviada, COALESCE(estado,'') FROM marcacion_ordenes WHERE id=?", (oid,)).fetchone()
    if not o:
        return jsonify({'error': 'Orden no existe'}), 404
    if o[2] != 'enviado':
        return jsonify({'error': f'Orden en estado {o[2]} · ya recibida o cerrada'}), 409
    serig = o[0]
    try:
        cant = float(d.get('cantidad_recibida') or 0)
    except (TypeError, ValueError):
        cant = 0
    if cant <= 0:
        cant = float(o[1] or 0)
    # CAS: reclamar la orden primero
    c.execute("UPDATE marcacion_ordenes SET cantidad_recibida=?, fecha_retorno=?, estado='recibido' WHERE id=? AND COALESCE(estado,'')='enviado'",
              (cant, _hoy, oid))
    if (c.rowcount or 0) == 0:
        conn.rollback()
        return jsonify({'error': 'Orden ya reclamada por otro', 'codigo': 'YA_RECIBIDA'}), 409
    # Entrada del serigrafiado en CUARENTENA → Calidad libera con el flujo MEE existente
    try:
        c.execute("INSERT INTO movimientos_mee (mee_codigo, tipo, cantidad, unidad, lote_ref, responsable, observaciones, estado) "
                  "VALUES (?, 'Entrada', ?, 'und', 'MARCACION-RET', ?, ?, 'CUARENTENA')",
                  (serig, cant, user, ('Retorno de marcacion · orden ' + str(oid) + ' · cuarentena (revisa Calidad)')))
    except Exception:
        # si el kardex no tiene estado, intentar sin estado (instancia vieja)
        try:
            c.execute("INSERT INTO movimientos_mee (mee_codigo, tipo, cantidad, unidad, lote_ref, responsable, observaciones) "
                      "VALUES (?, 'Entrada', ?, 'und', 'MARCACION-RET', ?, ?)",
                      (serig, cant, user, ('Retorno de marcacion · orden ' + str(oid))))
        except Exception as e:
            conn.rollback()
            return jsonify({'error': 'No se pudo registrar la entrada: ' + str(e)[:150]}), 500
    try:
        from audit_helpers import audit_log as _al
        _al(c, usuario=user, accion='MARCACION_RECIBIR', tabla='marcacion_ordenes', registro_id=oid,
            despues={'serigrafiado': serig, 'cantidad_recibida': cant})
    except Exception:
        pass
    conn.commit()
    # Campana a Calidad + Dirección Técnica: volvió un envase marcado, espera revisión de arte
    try:
        from config import CALIDAD_USERS, TECNICA_USERS
        from blueprints.notif import push_notif_multi
        _prod = ''
        try:
            _pr = c.execute("SELECT COALESCE(producto_nombre,'') FROM marcacion_ordenes WHERE id=?", (oid,)).fetchone()
            _prod = (_pr[0] if _pr else '') or ''
        except Exception:
            pass
        push_notif_multi(
            list(set(CALIDAD_USERS) | set(TECNICA_USERS)),
            'arte_envase', '🎨 Envase marcado por revisar',
            body=(serig + (' · ' + _prod if _prod else '') + ' volvió de marcación · revisá el arte para liberarlo'),
            link='/calidad#tab-cc', remitente='marcacion')
    except Exception:
        pass
    return jsonify({'ok': True, 'orden_id': oid, 'cantidad_recibida': cant})


@bp.route('/api/programacion/marcacion-arte-pendiente', methods=['GET'])
def marcacion_arte_pendiente():
    """Cola de 'arte de envases por revisar' (Sebastián 21-jul): órdenes de marcación en estado
    'recibido' (volvieron de serigrafía, en cuarentena) esperando el checklist de arte. Aparece en
    los módulos Calidad y Dirección Técnica para que ELLOS liberen (no en la pestaña de Compras)."""
    from config import TECNICA_USERS, CALIDAD_USERS, ADMIN_USERS
    u = (session.get('compras_user', '') or '').lower()
    if not u:
        return jsonify({'error': 'No autorizado'}), 401
    _ok = {x.lower() for x in (set(TECNICA_USERS) | set(CALIDAD_USERS) | set(ADMIN_USERS))}
    if u not in _ok:
        return jsonify({'error': 'Solo Calidad o Dirección Técnica', 'items': []}), 403
    conn = get_db(); c = conn.cursor()
    try:
        rows = c.execute(
            "SELECT mo.id, COALESCE(mo.producto_nombre,''), COALESCE(mo.base_codigo,''), "
            " mo.serigrafiado_codigo, COALESCE(mo.metodo,''), COALESCE(mo.proveedor,''), "
            " COALESCE(mo.cantidad_recibida, mo.cantidad_enviada, 0), COALESCE(mo.fecha_retorno,''), "
            " COALESCE(mm.descripcion,'') "
            "FROM marcacion_ordenes mo "
            "LEFT JOIN maestro_mee mm ON UPPER(TRIM(mm.codigo))=UPPER(TRIM(mo.serigrafiado_codigo)) "
            "WHERE COALESCE(mo.estado,'')='recibido' ORDER BY mo.fecha_retorno DESC, mo.id DESC").fetchall()
    except Exception as e:
        return jsonify({'error': str(e)[:150], 'items': []}), 500
    items = [{'id': r[0], 'producto': r[1], 'base': r[2], 'serigrafiado': r[3], 'metodo': r[4],
              'proveedor': r[5], 'cantidad': r[6], 'fecha_retorno': (r[7] or '')[:10],
              'serigrafiado_desc': r[8]} for r in rows]
    return jsonify({'ok': True, 'items': items, 'total': len(items)})


@bp.route('/api/programacion/marcacion-ordenes', methods=['GET'])
def marcacion_ordenes_lista():
    """Fase B · Lista las ordenes de marcacion (en curso primero)."""
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    conn = get_db()
    c = conn.cursor()
    out = []
    try:
        from datetime import datetime as _dtO, timedelta as _tdO
        _hoy_o = (_dtO.utcnow() - _tdO(hours=5)).date()
        for r in c.execute("SELECT id, base_codigo, serigrafiado_codigo, COALESCE(producto_nombre,''), "
                           "COALESCE(metodo,''), COALESCE(proveedor,''), COALESCE(cantidad_enviada,0), "
                           "COALESCE(cantidad_recibida,0), COALESCE(fecha_envio,''), COALESCE(fecha_retorno,''), "
                           "COALESCE(estado,''), COALESCE(fecha_alistar,''), COALESCE(hora_alistar,''), COALESCE(urgencia,'') FROM marcacion_ordenes "
                           "ORDER BY CASE WHEN COALESCE(estado,'')='enviado' THEN 0 ELSE 1 END, id DESC LIMIT 300").fetchall():
            _fa = r[11]
            _dias = None
            _urg = 'ok'
            try:
                if _fa:
                    _dias = (_dtO.fromisoformat(_fa[:10]).date() - _hoy_o).days
                    _urg = 'vencido' if _dias < 0 else ('urgente' if _dias <= 3 else ('proximo' if _dias <= 8 else 'ok'))
            except Exception:
                _dias = None
            out.append({'id': r[0], 'base': r[1], 'serigrafiado': r[2], 'producto': r[3], 'metodo': r[4],
                        'proveedor': r[5], 'cantidad_enviada': r[6], 'cantidad_recibida': r[7],
                        'fecha_envio': r[8], 'fecha_retorno': r[9], 'estado': r[10],
                        'fecha_alistar': _fa, 'dias_restantes': _dias, 'hora_alistar': r[12],
                        # ⚠ EL SEMÁFORO ESTABA MUERTO (4-ago). Era `r[13] or _urg`, y `r[13]` es la
                        # columna `urgencia`, que se escribe UNA vez al crear la orden con el valor
                        # 'media' y NUNCA se recalcula. Como 'media' siempre tiene valor, el `or`
                        # nunca llegaba al cálculo real: TODO salía amarillo, y una orden vencida
                        # hace cinco días se pintaba igual que una recién creada -- con el texto
                        # diciendo "hace 5d" al lado. El estado del tiempo se DERIVA de la fecha,
                        # no se teclea (M109: un indicador que alguien debe recordar actualizar
                        # termina viejo). La marca manual se conserva aparte, por si se usa.
                        'urgencia': _urg,
                        'urgencia_manual': (r[13] or '')})
    except Exception as e:
        return jsonify({'error': str(e)[:200], 'items': []}), 500
    return jsonify({'items': out, 'total': len(out)})


@bp.route('/api/programacion/marcacion-crear-envase', methods=['POST'])
def marcacion_crear_envase():
    """Crea un envase nuevo desde el modal de marcacion (normaliza: volumen, stock, proveedor, costo). Si el
    proveedor no existe, lo crea. Sebastian 30-jun."""
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    user = session.get('compras_user', '')
    d = request.json or {}
    cod = (d.get('codigo') or '').strip().upper()
    desc = (d.get('descripcion') or '').strip()
    cat = (d.get('categoria') or 'Envase').strip()
    prov = (d.get('proveedor') or '').strip()
    def _f(k):
        try:
            return float(d.get(k) or 0)
        except (TypeError, ValueError):
            return 0
    vol = _f('volumen_ml')
    stock = _f('stock_actual')
    smin = _f('stock_minimo')
    precio = _f('precio')
    if not cod or not desc:
        return jsonify({'error': 'codigo y descripcion requeridos'}), 400
    from datetime import datetime as _dtM, timedelta as _tdM
    _hoy = (_dtM.utcnow() - _tdM(hours=5)).date().isoformat()
    conn = get_db()
    c = conn.cursor()
    if c.execute("SELECT 1 FROM maestro_mee WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))", (cod,)).fetchone():
        return jsonify({'error': f'el envase {cod} ya existe'}), 409
    # proveedor: crear si no existe (para ir normalizando)
    if prov:
        try:
            c.execute("SAVEPOINT sp_marc_prov")
            if not c.execute("SELECT 1 FROM proveedores WHERE LOWER(TRIM(nombre))=LOWER(TRIM(?))", (prov,)).fetchone():
                c.execute("INSERT INTO proveedores (nombre, categoria, activo, fecha_creacion) VALUES (?, 'Envases', 1, ?)",
                          (prov, _hoy))
            c.execute("RELEASE SAVEPOINT sp_marc_prov")
        except Exception:
            try:
                c.execute("ROLLBACK TO SAVEPOINT sp_marc_prov")
            except Exception:
                pass
    # crear envase (columnas nuevas si existen; si no, fallback)
    try:
        c.execute("INSERT INTO maestro_mee (codigo, descripcion, categoria, unidad, proveedor, stock_actual, "
                  "stock_minimo, volumen_ml, precio_referencia, estado) VALUES (?,?,?,?,?,?,?,?,?,'Activo')",
                  (cod, desc, cat, 'und', prov, stock, smin, vol, precio))
    except Exception:
        c.execute("INSERT INTO maestro_mee (codigo, descripcion, categoria, unidad, proveedor, stock_actual, "
                  "stock_minimo, estado) VALUES (?,?,?,?,?,?,?,'Activo')",
                  (cod, desc, cat, 'und', prov, stock, smin))
    try:
        from audit_helpers import audit_log as _al
        _al(c, usuario=user, accion='CREAR_ENVASE_MARCACION', tabla='maestro_mee', registro_id=cod,
            despues={'descripcion': desc[:80], 'volumen_ml': vol, 'stock': stock, 'proveedor': prov, 'precio': precio})
    except Exception:
        pass
    conn.commit()
    return jsonify({'ok': True, 'codigo': cod})


@bp.route('/api/programacion/marcacion-vincular-sugerencias', methods=['GET'])
def marcacion_vincular_sugerencias():
    """Fase 1 base↔impreso (Sebastián 21-jul): sugiere el envase BASE de cada IMPRESO
    (serigrafiado) por coincidencia de nombre, para poblar maestro_mee.material_referencia
    (el vínculo que hace que al mandar a marcar el base vuelva como impreso). No escribe nada."""
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    import re as _re
    conn = get_db(); c = conn.cursor()
    rows = c.execute("SELECT codigo, COALESCE(descripcion,''), COALESCE(material_referencia,'') "
                     "FROM maestro_mee WHERE COALESCE(estado,'') NOT IN ('Inactivo','inactivo')").fetchall()

    def _norm(s):
        s = (s or '').upper()
        s = _re.sub(r'CON\s+SERIGRAF\w*', ' ', s)
        s = _re.sub(r'SIN\s+SERIGRAF\w*', ' ', s)
        s = _re.sub(r'SIN\s+SERIG\b', ' ', s)
        s = _re.sub(r'\bIMPRES[OA]\b', ' ', s)
        s = _re.sub(r'[^A-Z0-9]+', ' ', s)
        return ' '.join(s.split()).strip()

    impresos, bases = [], []
    for cod, desc, ref in rows:
        du = (desc or '').upper(); cu = (cod or '').upper()
        if ('CON SERIGRAF' in du) or ('-IMP-' in cu):
            impresos.append((cod, desc, ref, _norm(desc)))
        else:
            bases.append((cod, desc, _norm(desc)))
    base_idx = {}
    for bcod, bdesc, bnorm in bases:
        if bnorm:
            base_idx.setdefault(bnorm, []).append((bcod, bdesc))
    out = []
    for icod, idesc, iref, inorm in impresos:
        sug = base_idx.get(inorm, [])
        base_cod = sug[0][0] if len(sug) == 1 else ''
        base_desc = sug[0][1] if len(sug) == 1 else ''
        out.append({'impreso': icod, 'impreso_desc': idesc, 'base_actual': iref,
                    'base_sugerido': base_cod, 'base_sugerido_desc': base_desc,
                    'ambiguo': len(sug) > 1, 'ya_vinculado': bool((iref or '').strip())})
    out.sort(key=lambda x: (x['ya_vinculado'], not x['base_sugerido'], x['impreso']))
    return jsonify({'items': out, 'total': len(out),
                    'sin_vincular': sum(1 for x in out if not x['ya_vinculado']),
                    'bases': [{'codigo': b[0], 'descripcion': b[1]} for b in bases]})


@bp.route('/api/programacion/marcacion-vincular', methods=['POST'])
def marcacion_vincular():
    """Guarda vínculos base↔impreso confirmados: maestro_mee[impreso].material_referencia = base.
    Ambos códigos deben existir y ser distintos. Audita."""
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    user = session.get('compras_user', '')
    d = request.json or {}
    pares = d.get('pares') or []
    conn = get_db(); c = conn.cursor()
    n, errores = 0, []
    for p in pares:
        imp = (p.get('impreso') or '').strip()
        base = (p.get('base') or '').strip()
        if not imp or not base or imp.upper() == base.upper():
            continue
        if not c.execute("SELECT 1 FROM maestro_mee WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))", (imp,)).fetchone():
            errores.append(f'impreso {imp} no existe'); continue
        if not c.execute("SELECT 1 FROM maestro_mee WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))", (base,)).fetchone():
            errores.append(f'base {base} no existe'); continue
        c.execute("UPDATE maestro_mee SET material_referencia=? WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))", (base, imp))
        n += 1
    try:
        from audit_helpers import audit_log as _al
        _al(c, usuario=user, accion='VINCULAR_BASE_IMPRESO', tabla='maestro_mee',
            registro_id='(varios)', despues={'vinculados': n, 'errores': errores[:10]})
    except Exception:
        pass
    conn.commit()
    return jsonify({'ok': True, 'vinculados': n, 'errores': errores})


@bp.route('/api/programacion/marcacion-catalogos', methods=['GET'])
def marcacion_catalogos():
    """Listas para editar en la bandeja de marcación: proveedores existentes + todos los envases (para cambiar)."""
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    conn = get_db()
    c = conn.cursor()
    provs = []
    envs = []
    try:
        for r in c.execute("SELECT nombre FROM proveedores WHERE COALESCE(activo,1)=1 AND COALESCE(nombre,'')<>'' ORDER BY nombre").fetchall():
            provs.append(r[0])
    except Exception:
        pass
    try:
        for r in c.execute("SELECT codigo, COALESCE(descripcion,''), COALESCE(volumen_ml,0) FROM maestro_mee "
                           "WHERE COALESCE(estado,'Activo') NOT IN ('Inactivo','Descontinuado','Descontinuo') "
                           "ORDER BY descripcion").fetchall():
            envs.append({'codigo': r[0], 'descripcion': r[1], 'volumen': r[2]})
    except Exception:
        # maestro_mee puede no tener volumen_ml en instancias viejas
        try:
            for r in c.execute("SELECT codigo, COALESCE(descripcion,'') FROM maestro_mee ORDER BY descripcion").fetchall():
                envs.append({'codigo': r[0], 'descripcion': r[1], 'volumen': 0})
        except Exception:
            pass
    return jsonify({'proveedores': provs, 'envases': envs})


@bp.route('/api/programacion/marcacion-cambiar-envase', methods=['POST'])
def marcacion_cambiar_envase():
    """Catalina cambia el envase de una presentación (se agotó / es otro). Actualiza producto_presentaciones →
    la cola, el abastecimiento y la marcación lo reflejan. Sebastián 30-jun."""
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    user = session.get('compras_user', '')
    d = request.json or {}
    producto = (d.get('producto') or '').strip()
    env_old = (d.get('envase_actual') or '').strip()
    env_new = (d.get('envase_nuevo') or '').strip()
    try:
        vol = float(d.get('volumen_ml') or 0)
    except (TypeError, ValueError):
        vol = 0
    if not producto or not env_new:
        return jsonify({'error': 'producto y envase_nuevo requeridos'}), 400
    conn = get_db()
    c = conn.cursor()
    if not c.execute("SELECT 1 FROM maestro_mee WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))", (env_new,)).fetchone():
        return jsonify({'error': f'el envase {env_new} no existe'}), 400
    c.execute("UPDATE producto_presentaciones SET envase_codigo=? "
              "WHERE UPPER(TRIM(producto_nombre))=UPPER(TRIM(?)) AND ROUND(COALESCE(volumen_ml,0),2)=ROUND(?,2) "
              "AND UPPER(TRIM(COALESCE(envase_codigo,'')))=UPPER(TRIM(?))",
              (env_new, producto, vol, env_old))
    n = c.rowcount or 0
    if n == 0:
        c.execute("UPDATE producto_presentaciones SET envase_codigo=? "
                  "WHERE UPPER(TRIM(producto_nombre))=UPPER(TRIM(?)) AND ROUND(COALESCE(volumen_ml,0),2)=ROUND(?,2)",
                  (env_new, producto, vol))
        n = c.rowcount or 0
    if n == 0:
        return jsonify({'error': 'no encontré la presentación a cambiar'}), 404
    try:
        from audit_helpers import audit_log as _al
        _al(c, usuario=user, accion='MARCACION_CAMBIAR_ENVASE', tabla='producto_presentaciones', registro_id=producto,
            antes={'envase': env_old}, despues={'envase': env_new, 'volumen_ml': vol})
    except Exception:
        pass
    conn.commit()
    return jsonify({'ok': True, 'cambiadas': n})


@bp.route('/api/admin/marcacion-envase', methods=['POST'])
def marcacion_envase_set():
    """Compras define el metodo de marcacion (serigrafia/tampografia/pre_impreso/ninguno) + proveedor de un envase.
    Se recuerda (fijo por envase, editable). Sebastian 29-jun."""
    if 'compras_user' not in session:
        return jsonify({'error': 'No autorizado'}), 401
    d = request.json or {}
    cod = (d.get('codigo') or '').strip()
    tipo = (d.get('marcacion_tipo') or '').strip()
    prov = (d.get('marcacion_proveedor') or '').strip()
    if not cod:
        return jsonify({'error': 'codigo requerido'}), 400
    if tipo and tipo not in ('serigrafia', 'tampografia', 'etiqueta', 'pre_impreso', 'ninguno'):
        return jsonify({'error': 'tipo invalido'}), 400
    conn = get_db()
    c = conn.cursor()
    # Lo de ANTES: este campo decide si el envase sale a serigrafía y con qué proveedor, o sea si
    # entra a la cola de marcación y a qué se le paga. Sin el valor previo no se puede revertir.
    _prev = None
    try:
        _r = c.execute("SELECT COALESCE(marcacion_tipo,''), COALESCE(marcacion_proveedor,'') "
                       "  FROM maestro_mee WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))",
                       (cod,)).fetchone()
        _prev = ({'marcacion_tipo': _r[0], 'marcacion_proveedor': _r[1]} if _r else None)
    except Exception:
        _prev = None
    try:
        c.execute("UPDATE maestro_mee SET marcacion_tipo=?, marcacion_proveedor=? WHERE UPPER(TRIM(codigo))=UPPER(TRIM(?))",
                  (tipo, prov, cod))
    except Exception as e:
        return jsonify({'error': str(e)[:200]}), 500
    if c.rowcount == 0:
        return jsonify({'error': 'envase no encontrado'}), 404
    try:
        audit_log(c, usuario=session.get('compras_user', ''), accion='MEE_MARCACION',
                  tabla='maestro_mee', registro_id=cod,
                  antes=_prev if _prev is not None else {'valor': 'no se pudo leer'},
                  despues={'marcacion_tipo': tipo, 'marcacion_proveedor': prov},
                  detalle='método de marcación de %s = %s (%s)' % (cod, tipo or '(vacío)',
                                                                  prov or 'sin proveedor'))
    except Exception as _ae:
        import logging as _lg
        _lg.getLogger('programacion').warning('audit MEE_MARCACION falló: %s', _ae)
    conn.commit()
    return jsonify({'ok': True, 'codigo': cod, 'marcacion_tipo': tipo, 'marcacion_proveedor': prov})


def _tokens_tono(texto):
    """Las palabras que IDENTIFICAN el tono, sacando el ruido comun del nombre del envase.

    'LIPS GLOSS PEACH' -> ['PEACH'] · 'FRASCO VIDRIO 30 ML AMBAR' -> ['AMBAR'].
    """
    import re as _re
    import unicodedata as _ud
    n = _ud.normalize('NFKD', str(texto or '')).encode('ascii', 'ignore').decode().upper()
    n = _re.sub(r'[^A-Z0-9]+', ' ', n)
    RUIDO = {'LIPS', 'LIP', 'GLOSS', 'SERUM', 'LABIAL', 'LABIO', 'LABIOS', 'VOLUMINIZADOR',
             'PEPTIDOS', 'SIN', 'SERG', 'SERIG', 'SERIGRAFIA', 'SERIGRAFIADO', 'TAMPOGRAFIA',
             'CON', 'DE', 'ML', 'ENVASE', 'FRASCO', 'NUEVA', 'FORMULA', 'COLAPSIBLE', 'FR',
             'VID', 'VIDRIO', 'PLA', 'PLASTICO', 'TONO', 'COLOR', 'LOTE', 'MEE', 'IMP', 'ENV',
             'TAPA', 'CAJA', 'AIRLESS', 'GOTERO', 'PET', 'PP'}
    return [t for t in n.split() if t not in RUIDO and not t.isdigit() and len(t) > 2]


# Que categoria del maestro corresponde a cada columna. Se enumeran las variantes reales que hay
# cargadas (Frasco y Envase conviven, Plegadiza y Plegable tambien): adivinar por parecido dejaria
# la lista de opciones incompleta justo en el producto raro.
_MEE_CATS = {
    # Sebastian (9-ago): *"la tapa seria gotero... sigue sin salirme la opcion del gotero"*. No
    # salia porque `Gotero` es una CATEGORIA PROPIA del maestro y esta columna solo ofrecia `TAPA`:
    # los tres goteros existian y la pantalla no los mostraba, que desde la silla del usuario es lo
    # mismo que no tenerlos (M121).
    'envase':   ('FRASCO', 'ENVASE', 'CONTORNO', 'SERIGRAFIA', 'IMPRESION', 'TAMPOGRAFIA'),
    'tapa':     ('TAPA', 'GOTERO', 'VALVULA', 'DOSIFICADOR', 'TAPON', 'SPRAY', 'BOMBA', 'PUMP'),
    'etiqueta': ('ETIQUETA', 'ROTULO', 'STICKER'),
    'caja':     ('PLEGADIZA', 'PLEGABLE', 'CAJA', 'ESTUCHE'),
}
# ⚠ La categoria real trae TILDE (`Impresion` se guarda como "Impresi\u00f3n"), asi que comparar
# con UPPER() a secas no la encuentra NUNCA: el envase ya serigrafiado -- justo el que viene
# impreso de China -- quedaba fuera de la lista sin que nada avisara.
def _cat_norm(x):
    import unicodedata as _ud
    n = _ud.normalize('NFKD', str(x or '')).encode('ascii', 'ignore').decode()
    return n.strip().upper()


def _tokens_nombre(texto):
    """Las palabras que IDENTIFICAN algo, sin el ruido que comparten todos los envases."""
    import re as _re
    import unicodedata as _ud
    n = _ud.normalize('NFKD', str(texto or '')).encode('ascii', 'ignore').decode().upper()
    n = _re.sub(r'[^A-Z0-9]+', ' ', n)
    RUIDO = {'MEE', 'ENV', 'IMP', 'FR', 'ML', 'GR', 'UN', 'UND', 'DE', 'DEL', 'LA', 'EL', 'CON',
             'SIN', 'PARA', 'FRASCO', 'ENVASE', 'TAPA', 'ETIQUETA', 'CAJA', 'PLEGADIZA',
             'PLEGABLE', 'BOTELLA', 'POTE', 'TARRO', 'VIDRIO', 'PET', 'PP', 'PEAD', 'PLASTICO',
             'AIRLESS', 'GOTERO', 'SERIGRAFIA', 'SERIGRAFIADO', 'IMPRESION', 'IMPRESO', 'BLANCO',
             'NEGRO', 'TRANSPARENTE', 'AMBAR', 'NUEVA', 'FORMULA', 'PRODUCTO', 'LOTE', 'TONO'}
    return [t for t in n.split() if t not in RUIDO and not t.isdigit() and len(t) > 2]


